// Package upkeep pays people to run the ecosystem's permissionless
// valves. The portfolio's realms deliberately expose maintenance
// entrypoints that anyone may call — subscriptions.Expire frees a lapsed
// subscription slot, timelock_guardian.Execute fires a matured timelocked
// action — because no slot's liveness may depend on an interested party
// showing up. This realm adds the missing economics: funders finance a
// reward pot, and whoever triggers a valve THROUGH this realm is credited
// a bounded reward, claimable by pull.
//
// THE REALM-TO-REALM BOUNDARY, PRECISELY:
//
//	which calls which     : upkeep -> subscriptions.Expire(cross, id)
//	                        upkeep -> timelock_guardian.Execute(cross, id)
//	why it is necessary   : the reward must be conditioned on the valve
//	                        actually firing. Only making the call from
//	                        inside this realm ties "the valve fired" and
//	                        "the reward is credited" into one atomic
//	                        transaction; observing from outside cannot.
//	caller identity       : downstream sees cur.Previous() = THIS realm,
//	                        not the poking EOA. Both valves are
//	                        permissionless BY DESIGN and use the caller
//	                        identity for nothing, so the intermediary
//	                        changes no authorization outcome. This realm
//	                        is not a deputy for any downstream authority
//	                        — it holds none to confuse.
//	authorization boundary: upstream, anyone may poke (the reward is the
//	                        only thing at stake and the pot is the only
//	                        source). Downstream, each valve enforces its
//	                        own STATE conditions (grace elapsed, delay
//	                        matured) exactly as it would for a direct
//	                        caller.
//	ordering              : downstream call FIRST, reward accounting
//	                        AFTER. A downstream abort therefore reverts
//	                        the whole transaction before any pot or
//	                        ledger mutation exists.
//	failure behavior      : any downstream panic (not expirable, too
//	                        early, already executed, unknown id...)
//	                        aborts this transaction. No partial state,
//	                        no reward, by VM atomicity — not by cleanup
//	                        code.
//	atomicity assumptions : a Gno transaction is all-or-nothing across
//	                        realm boundaries; there is no catch/recover
//	                        anywhere on this path (and none may be added
//	                        — recovery would break exactly this
//	                        guarantee).
//	value movement        : none crosses the boundary. Both valves move
//	                        no coins; the poke transaction must carry no
//	                        coins (subscriptions' assertNoSend reads the
//	                        ORIGIN envelope unconditionally — measured,
//	                        not assumed). Rewards move only inside this
//	                        realm's ledger, funded by explicit Fund
//	                        transactions.
//	downstream rejection  : reward denied automatically — the abort is
//	                        the denial.
//	downstream trust      : neither valve trusts nor validates the
//	                        caller; both validate state. This realm
//	                        symmetrically does not trust the downstream
//	                        REPLY beyond "it did not abort".
//	replay                : enforced downstream. A second Expire on the
//	                        same subscription aborts ("subscription is
//	                        expired"); a second Execute aborts ("action
//	                        already executed"). A poker cannot be paid
//	                        twice for one valve event.
//	adversarial callers   : an EOA or realm poking with bogus ids,
//	                        premature targets, or replays hits a
//	                        downstream abort and pays its own gas. The
//	                        remaining economic edge — manufacturing
//	                        expirable state to farm rewards — differs
//	                        per task. sub_expire: every farmed
//	                        subscription permanently locks a sub-record
//	                        storage deposit of roughly 30,000ugnot at
//	                        the observed 100ugnot/byte rate (Expire
//	                        flips status; it does not free the record),
//	                        which exceeds MaxReward before price and
//	                        gas — loss-making at any legal setting.
//	                        timelock_execute: a farmed Action record is
//	                        small and its deposit can sit below the
//	                        cap, so farming resistance there rests on
//	                        the admin keeping the setting below the
//	                        measured cycle cost. Funders trust the cap
//	                        AND the admin's reward policy, not the cap
//	                        alone. The pot is a donation either way —
//	                        farming can drain it, never third-party
//	                        balances.
//
// Rewards default to 0 per task; the admin sets them within the
// compile-time MaxReward. The pot only moves down via successful pokes
// and only up via Fund. Conservation: Held == pot + UsersTotal
// (+ out-of-band surplus, recoverable above that reserve by SweepDenom).
// The ledger's fee cap is 0 — no fee exists anywhere in this realm.
package upkeep

import (
	"chain"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/g1qp5pt8cdq2f6kfdamn3yuxwg6quqnfpyewzz39/coinio"
	"gno.land/p/g1qp5pt8cdq2f6kfdamn3yuxwg6quqnfpyewzz39/feeledger"

	subs "gno.land/r/g1qp5pt8cdq2f6kfdamn3yuxwg6quqnfpyewzz39/subscriptions"
	guardian "gno.land/r/g1qp5pt8cdq2f6kfdamn3yuxwg6quqnfpyewzz39/timelock_guardian"
)

// Denom is the only asset this realm accepts.
const Denom = "ugnot"

// Task identifiers — the two supported valves.
const (
	TaskSubExpire       = "sub_expire"
	TaskTimelockExecute = "timelock_execute"
)

// MaxReward is the compile-time ceiling on the per-poke reward:
// 20,000ugnot (0.02 GNOT). It bounds what any single poke can extract
// from the pot. For sub_expire it also defeats farming outright: one
// manufactured expirable subscription permanently locks a sub-record
// deposit of ~30,000ugnot at the observed 100ugnot/byte rate — already
// above the cap before price and gas. For timelock_execute the farmed
// Action record is smaller and its deposit can sit below the cap, so
// there the admin's setting, kept below the measured farm-cycle cost,
// is what deters farming. Funders trust the cap and the admin's
// policy together; the pot they fund is an explicit donation either
// way.
const MaxReward = int64(20000)

var (
	admin        address // may set rewards, stage a successor
	pendingAdmin address // staged by TransferAdmin, completes via AcceptAdmin
	sweeper      address // may sweep out-of-band surplus

	self address // this realm's address, captured at deploy
	pot  int64   // funded, not-yet-awarded ugnot

	rewards = map[string]int64{
		TaskSubExpire:       0,
		TaskTimelockExecute: 0,
	}
	ledger = feeledger.MustNew(0)

	// lifetime counters, rendered for operators
	pokes  int64
	funded int64
)

func init() {
	admin = unsafe.OriginCaller()
	sweeper = admin
	self = unsafe.CurrentRealm().Address()
}

// --- funding ---

// Fund adds the attached coins to the reward pot. Anyone may fund;
// funding is a donation to ecosystem maintenance and is not refundable.
func Fund(cur realm) {
	funder, amount := coinio.Receive(0, cur, Denom)
	newPot, ok := checkedAdd(pot, amount)
	if !ok {
		panic("pot would overflow")
	}
	pot = newPot
	funded += amount
	chain.Emit("Funded", "from", funder.String(), "amount", itoa(amount),
		"pot", itoa(pot))
}

// --- the pokes: the realm-to-realm calls ---

// PokeExpire triggers subscriptions.Expire(subID) through this realm and
// credits the caller the sub_expire reward. The downstream realm decides
// whether the subscription is expirable; its abort is the authorization.
// The transaction must attach no coins (the downstream realm checks the
// origin envelope).
func PokeExpire(cur realm, subID int64) {
	assertNoSend()
	caller := cur.Previous().Address()
	reward := requireReward(TaskSubExpire)

	// Downstream first: an abort here reverts everything below.
	subs.Expire(cross(cur), subID)

	award(caller, reward, TaskSubExpire, itoa(subID))
}

// PokeExecute triggers timelock_guardian.Execute(actionID) through this
// realm and credits the caller the timelock_execute reward. The guardian
// decides whether the action is executable; its abort is the
// authorization.
func PokeExecute(cur realm, actionID string) {
	assertNoSend()
	caller := cur.Previous().Address()
	reward := requireReward(TaskTimelockExecute)

	guardian.Execute(cross(cur), actionID)

	award(caller, reward, TaskTimelockExecute, actionID)
}

// award moves reward from the pot to the caller's claimable balance.
// Callers have already established that the pot covers it.
func award(caller address, reward int64, task, target string) {
	pot -= reward
	ledger.MustDeposit(caller.String(), reward, 0)
	pokes++
	chain.Emit("Poked",
		"task", task,
		"target", target,
		"caller", caller.String(),
		"reward", itoa(reward),
		"pot", itoa(pot),
	)
}

// requireReward returns the configured reward for a task, refusing when
// the task is unknown, unrewarded, or the pot cannot cover it. Refusal
// on an empty pot is deliberate: both valves remain directly callable on
// their own realms, so an unrewarded detour through this one is only a
// gas trap for the caller.
func requireReward(task string) int64 {
	r, ok := rewards[task]
	if !ok {
		panic("unknown task: " + task)
	}
	if r <= 0 {
		panic("no reward configured for " + task)
	}
	if pot < r {
		panic("reward pot cannot cover " + task + ": pot " + itoa(pot) +
			", reward " + itoa(r))
	}
	return r
}

// --- claims ---

// Claim sends amount ugnot of the caller's earned balance back to the
// caller.
func Claim(cur realm, amount int64) {
	assertNoSend()
	caller := cur.Previous().Address()
	if err := ledger.Withdraw(caller.String(), amount); err != nil {
		panic(err)
	}
	coinio.Payout(0, cur, caller, Denom, amount)
	chain.Emit("Claim", "to", caller.String(), "amount", itoa(amount))
}

// ClaimAll sends the caller's entire earned balance back to the caller.
func ClaimAll(cur realm) {
	assertNoSend()
	caller := cur.Previous().Address()
	amount, err := ledger.WithdrawAll(caller.String())
	if err != nil {
		panic(err)
	}
	if amount == 0 {
		panic("nothing to claim")
	}
	coinio.Payout(0, cur, caller, Denom, amount)
	chain.Emit("Claim", "to", caller.String(), "amount", itoa(amount))
}

// --- administration ---

// SetReward configures the per-poke reward for a task, bounded by
// MaxReward. Admin only. Zero disables the task.
func SetReward(cur realm, task string, amount int64) {
	assertNoSend()
	assertAdmin(cur.Previous().Address())
	if _, ok := rewards[task]; !ok {
		panic("unknown task: " + task)
	}
	if amount < 0 || amount > MaxReward {
		panic("reward must be in [0, " + itoa(MaxReward) + "]")
	}
	old := rewards[task]
	rewards[task] = amount
	chain.Emit("RewardChanged", "task", task, "old", itoa(old), "new", itoa(amount))
}

// SweepDenom recovers out-of-band coins to the sweeper. For the pot
// denom the reserve is pot + earned balances — both structurally
// unreachable. Sweeper only.
func SweepDenom(cur realm, denom string) {
	assertNoSend()
	if cur.Previous().Address() != sweeper {
		panic("sweeper only")
	}
	reserve := int64(0)
	if denom == Denom {
		reserve = pot + ledger.Liabilities()
	}
	swept := coinio.Sweep(0, cur, sweeper, denom, reserve)
	chain.Emit("SurplusSwept", "to", sweeper.String(), "coins", itoa(swept)+denom)
}

// TransferAdmin stages a two-step admin handover.
func TransferAdmin(cur realm, successor address) {
	assertNoSend()
	assertAdmin(cur.Previous().Address())
	var zero address
	if successor == zero {
		panic("successor must not be the zero address")
	}
	pendingAdmin = successor
	chain.Emit("AdminTransferStaged", "from", admin.String(), "to", successor.String())
}

// AcceptAdmin completes the handover; only the staged successor may.
// The sweeper role moves with the admin.
func AcceptAdmin(cur realm) {
	assertNoSend()
	caller := cur.Previous().Address()
	if caller != pendingAdmin {
		panic("only the staged successor may accept")
	}
	old := admin
	admin = caller
	sweeper = caller
	var zero address
	pendingAdmin = zero
	chain.Emit("AdminTransferred", "from", old.String(), "to", admin.String())
}

// --- views ---

func Admin() address        { return admin }
func PendingAdmin() address { return pendingAdmin }
func Pot() int64            { return pot }
func RewardFor(task string) int64 {
	r, ok := rewards[task]
	if !ok {
		panic("unknown task: " + task)
	}
	return r
}
func BalanceOf(a address) int64 { return ledger.BalanceOf(a.String()) }
func UsersTotal() int64         { return ledger.UsersTotal() }
func Pokes() int64              { return pokes }
func Funded() int64             { return funded }
func Address() address          { return self }
func Held() int64               { return coinio.HeldAt(self, Denom) }

// --- render ---

func Render(path string) string {
	if path != "" {
		return "unknown page; try the realm root"
	}
	out := "# upkeep\n\n"
	out += "Rewards for running the ecosystem's permissionless valves. " +
		"Fund the pot; poke a valve through this realm; claim what you " +
		"earn. A poke succeeds only when the downstream realm accepts " +
		"the valve call in the same transaction.\n\n"
	out += "- pot: " + itoa(pot) + Denom + "\n"
	out += "- earned, unclaimed: " + itoa(ledger.UsersTotal()) + Denom + "\n"
	out += "- lifetime pokes: " + itoa(pokes) + "\n"
	out += "- lifetime funding: " + itoa(funded) + Denom + "\n\n"
	out += "## rewards per poke\n\n"
	out += "- `" + TaskSubExpire + "` (subscriptions.Expire): " +
		itoa(rewards[TaskSubExpire]) + Denom + "\n"
	out += "- `" + TaskTimelockExecute + "` (timelock_guardian.Execute): " +
		itoa(rewards[TaskTimelockExecute]) + Denom + "\n"
	out += "\n(cap per poke: " + itoa(MaxReward) + Denom + ", compile-time)\n"
	return out
}

// --- internals ---

func assertNoSend() {
	if len(unsafe.OriginSend()) != 0 {
		panic("this function does not accept coins")
	}
}

func assertAdmin(caller address) {
	if caller != admin {
		panic("admin only")
	}
}

func checkedAdd(a, b int64) (int64, bool) {
	if b > 0 && a > int64(^uint64(0)>>1)-b {
		return 0, false
	}
	return a + b, true
}

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

package upkeep

import (
	"chain"
	"chain/banker"
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"

	subs "gno.land/r/g1qp5pt8cdq2f6kfdamn3yuxwg6quqnfpyewzz39/subscriptions"
	guardian "gno.land/r/g1qp5pt8cdq2f6kfdamn3yuxwg6quqnfpyewzz39/timelock_guardian"
)

var (
	testAdmin = testutils.TestAddress("ukadmin")
	funder    = testutils.TestAddress("ukfunder")
	poker     = testutils.TestAddress("ukpoker")
	mallory   = testutils.TestAddress("ukmallory")
	provider  = testutils.TestAddress("ukprov")
	subber    = testutils.TestAddress("uksubber")
	towner    = testutils.TestAddress("uktowner")
)

// Harness facts, carried from the sibling suites: init runs with an
// empty origin (real deploys capture the signer); realm globals persist
// across tests while the banker resets; SetRealm binds to the CALLING
// frame only, so arming is inlined at every site; SkipHeights advances
// the clock 5s per height AND wipes the origin context.
func init() {
	admin = testAdmin
	sweeper = testAdmin
	self = chain.PackageAddress("gno.land/r/g1qp5pt8cdq2f6kfdamn3yuxwg6quqnfpyewzz39/upkeep")
}

func ugnot(n int64) chain.Coins { return chain.NewCoins(chain.NewCoin(Denom, n)) }

func coinsOf(a address) int64 { return banker.NewReadonlyBanker().GetCoin(a, Denom) }

// conserved asserts the realm's monetary invariant: everything the realm
// holds is either unspent pot or earned-but-unclaimed balance.
func conserved(t *testing.T) {
	t.Helper()
	if Held() != Pot()+UsersTotal() {
		t.Fatalf("conservation violated: Held=%d pot=%d users=%d",
			Held(), Pot(), UsersTotal())
	}
}

// syncHeld re-issues the realm's expected holdings. The harness banker
// resets between tests while realm globals (pot, ledger) persist, so
// each money-touching test starts by making the banker match the books.
func syncHeld() {
	want := Pot() + UsersTotal()
	have := coinsOf(Address())
	if want > have {
		testing.IssueCoins(Address(), ugnot(want-have))
	}
}

func fundAs(cur realm, from address, amount int64) {
	testing.SetRealm(testing.NewUserRealm(from))
	testing.SetOriginCaller(from)
	testing.SetOriginSend(ugnot(amount))
	testing.IssueCoins(Address(), ugnot(amount))
	Fund(cross(cur))
}

func adminSet(cur realm, task string, amount int64) {
	testing.SetRealm(testing.NewUserRealm(testAdmin))
	testing.SetOriginCaller(testAdmin)
	testing.SetOriginSend(nil)
	SetReward(cross(cur), task, amount)
}

// expirableSub drives the REAL subscriptions realm to a state where one
// subscription is past its grace window, and returns its id. This is
// the downstream fixture for the realm-to-realm tests: nothing is
// mocked.
func expirableSub(cur realm, t *testing.T) int64 {
	t.Helper()
	testing.SetRealm(testing.NewUserRealm(provider))
	testing.SetOriginCaller(provider)
	testing.SetOriginSend(nil)
	planID := subs.CreatePlan(cross(cur), "upkeep-fixture", "d", 1, 10, 1000)

	testing.SetRealm(testing.NewUserRealm(subber))
	testing.SetOriginCaller(subber)
	testing.SetOriginSend(ugnot(1))
	testing.IssueCoins(subs.Address(), ugnot(1))
	subID := subs.Subscribe(cross(cur), planID)

	// paidThrough = h+10; expirable at paidThrough+10. Skip well past.
	testing.SkipHeights(25)
	return subID
}

// maturedAction drives the REAL guardian realm to a matured timelocked
// action and returns its id.
var targetSeq int

func maturedAction(cur realm, t *testing.T) string {
	t.Helper()
	targetSeq++
	name := "uktarget" + string(rune('a'+targetSeq%26))
	testing.SetRealm(testing.NewUserRealm(towner))
	testing.SetOriginCaller(towner)
	testing.SetOriginSend(nil)
	guardian.RegisterTarget(cross(cur), name, guardian.MinDelayFloor, "")

	testing.SetRealm(testing.NewUserRealm(towner))
	testing.SetOriginCaller(towner)
	testing.SetOriginSend(nil)
	id := guardian.Schedule(cross(cur), name, "poke-fixture", guardian.MinDelayFloor)

	testing.SkipHeights(13) // 65s at 5s/height >= the 60s floor
	return id
}

func TestInitialState(t *testing.T) {
	if Admin() != testAdmin || Pot() != 0 || Pokes() != 0 || Funded() != 0 {
		t.Fatal("unexpected initial state")
	}
	if RewardFor(TaskSubExpire) != 0 || RewardFor(TaskTimelockExecute) != 0 {
		t.Fatal("rewards must default to 0")
	}
	conserved(t)
}

func TestFundAndRewardConfig(cur realm, t *testing.T) {
	fundAs(cur, funder, 100000)
	if Pot() != 100000 || Funded() != 100000 {
		t.Fatalf("pot=%d funded=%d", Pot(), Funded())
	}
	conserved(t)

	testing.SetRealm(testing.NewUserRealm(mallory))
	testing.SetOriginCaller(mallory)
	testing.SetOriginSend(nil)
	uassert.AbortsWithMessage(t, cur, "admin only", func() {
		SetReward(cross(cur), TaskSubExpire, 100)
	})

	testing.SetRealm(testing.NewUserRealm(testAdmin))
	testing.SetOriginCaller(testAdmin)
	testing.SetOriginSend(nil)
	uassert.AbortsContains(t, cur, "reward must be in", func() {
		SetReward(cross(cur), TaskSubExpire, MaxReward+1)
	})
	uassert.AbortsContains(t, cur, "unknown task", func() {
		SetReward(cross(cur), "nosuch", 1)
	})

	adminSet(cur, TaskSubExpire, 5000)
	adminSet(cur, TaskTimelockExecute, 7000)
	if RewardFor(TaskSubExpire) != 5000 || RewardFor(TaskTimelockExecute) != 7000 {
		t.Fatal("rewards not set")
	}
}

// The realm-to-realm happy path: poke the REAL subscriptions realm.
func TestPokeExpire(cur realm, t *testing.T) {
	syncHeld()
	subID := expirableSub(cur, t)

	// Downstream state before: still Active.
	_, _, _, _, _, _, status := subs.SubInfo(subID)
	if status != "active" {
		t.Fatalf("fixture status %q", status)
	}

	potBefore, balBefore := Pot(), BalanceOf(poker)
	testing.SetRealm(testing.NewUserRealm(poker))
	testing.SetOriginCaller(poker)
	testing.SetOriginSend(nil)
	PokeExpire(cross(cur), subID)

	// Downstream state changed by OUR realm's crossing call...
	_, _, _, _, _, _, status = subs.SubInfo(subID)
	if status != "expired" {
		t.Fatalf("downstream not expired: %q", status)
	}
	// ...and the reward moved pot -> caller balance atomically.
	if Pot() != potBefore-5000 || BalanceOf(poker) != balBefore+5000 {
		t.Fatalf("reward accounting wrong: pot %d->%d bal %d->%d",
			potBefore, Pot(), balBefore, BalanceOf(poker))
	}
	if Pokes() != 1 {
		t.Fatalf("pokes=%d", Pokes())
	}
	conserved(t)
}

// Replay: the downstream realm is the replay guard; a second poke on the
// same subscription aborts THERE and no reward is paid HERE.
func TestPokeExpireReplay(cur realm, t *testing.T) {
	syncHeld()
	potBefore, balBefore := Pot(), BalanceOf(mallory)
	testing.SetRealm(testing.NewUserRealm(mallory))
	testing.SetOriginCaller(mallory)
	testing.SetOriginSend(nil)
	uassert.AbortsContains(t, cur, "subscription is expired", func() {
		PokeExpire(cross(cur), 0) // the sub expired in TestPokeExpire
	})
	if Pot() != potBefore || BalanceOf(mallory) != balBefore || Pokes() != 1 {
		t.Fatal("aborted poke mutated reward state")
	}
	conserved(t)
}

// A premature poke aborts downstream ("not expirable") and pays nothing.
func TestPokeExpirePremature(cur realm, t *testing.T) {
	syncHeld()
	testing.SetRealm(testing.NewUserRealm(provider))
	testing.SetOriginCaller(provider)
	testing.SetOriginSend(nil)
	planID := subs.CreatePlan(cross(cur), "fresh", "d", 1, 5000, 1000)
	testing.SetRealm(testing.NewUserRealm(subber))
	testing.SetOriginCaller(subber)
	testing.SetOriginSend(ugnot(1))
	testing.IssueCoins(subs.Address(), ugnot(1))
	freshID := subs.Subscribe(cross(cur), planID)

	potBefore := Pot()
	testing.SetRealm(testing.NewUserRealm(poker))
	testing.SetOriginCaller(poker)
	testing.SetOriginSend(nil)
	uassert.AbortsContains(t, cur, "not expirable", func() {
		PokeExpire(cross(cur), freshID)
	})
	uassert.AbortsContains(t, cur, "unknown subscription id", func() {
		PokeExpire(cross(cur), 99999)
	})
	if Pot() != potBefore {
		t.Fatal("failed pokes touched the pot")
	}
	conserved(t)
}

// The second realm-to-realm integration: the REAL guardian realm.
func TestPokeExecute(cur realm, t *testing.T) {
	syncHeld()
	id := maturedAction(cur, t)
	potBefore, balBefore := Pot(), BalanceOf(poker)

	testing.SetRealm(testing.NewUserRealm(poker))
	testing.SetOriginCaller(poker)
	testing.SetOriginSend(nil)
	PokeExecute(cross(cur), id)

	if Pot() != potBefore-7000 || BalanceOf(poker) != balBefore+7000 {
		t.Fatal("timelock reward accounting wrong")
	}
	// Replay refused downstream.
	testing.SetRealm(testing.NewUserRealm(mallory))
	testing.SetOriginCaller(mallory)
	testing.SetOriginSend(nil)
	uassert.AbortsContains(t, cur, "already executed", func() {
		PokeExecute(cross(cur), id)
	})
	uassert.AbortsContains(t, cur, "action not found", func() {
		PokeExecute(cross(cur), "tl-nosuch")
	})
	// Premature: schedule a new one, poke before maturity.
	testing.SetRealm(testing.NewUserRealm(towner))
	testing.SetOriginCaller(towner)
	testing.SetOriginSend(nil)
	guardian.RegisterTarget(cross(cur), "ukearly", guardian.MinDelayFloor, "")
	testing.SetRealm(testing.NewUserRealm(towner))
	testing.SetOriginCaller(towner)
	testing.SetOriginSend(nil)
	early := guardian.Schedule(cross(cur), "ukearly", "x", guardian.MinDelayFloor)
	testing.SetRealm(testing.NewUserRealm(poker))
	testing.SetOriginCaller(poker)
	testing.SetOriginSend(nil)
	uassert.AbortsContains(t, cur, "too early", func() {
		PokeExecute(cross(cur), early)
	})
	conserved(t)
}

// Pot exhaustion refuses BEFORE the downstream call: no valve fires
// unrewarded through this realm. Entering here the pot is deterministic:
// 100000 funded minus the 5000 and 7000 awarded above = 88000, so four
// MaxReward pokes leave 8000 < MaxReward and the next must refuse.
func TestPotExhaustion(cur realm, t *testing.T) {
	syncHeld()
	adminSet(cur, TaskSubExpire, MaxReward)

	// Drain by REAL pokes until the pot no longer covers the reward.
	for i := 0; Pot() >= MaxReward; i++ {
		if i >= 10 {
			t.Fatalf("fixture arithmetic broken: pot=%d after %d pokes", Pot(), i)
		}
		id := expirableSub(cur, t)
		testing.SetRealm(testing.NewUserRealm(poker))
		testing.SetOriginCaller(poker)
		testing.SetOriginSend(nil)
		PokeExpire(cross(cur), id)
	}

	short := expirableSub(cur, t)
	potBefore := Pot()
	testing.SetRealm(testing.NewUserRealm(poker))
	testing.SetOriginCaller(poker)
	testing.SetOriginSend(nil)
	uassert.AbortsContains(t, cur, "reward pot cannot cover", func() {
		PokeExpire(cross(cur), short)
	})
	// Downstream MUST be untouched by the refused poke.
	_, _, _, _, _, _, status := subs.SubInfo(short)
	if status != "active" {
		t.Fatal("refused poke reached the downstream realm")
	}
	if Pot() != potBefore {
		t.Fatal("refused poke touched the pot")
	}
	conserved(t)
	adminSet(cur, TaskSubExpire, 5000) // restore for the later tests
}

// The refusal boundary, deterministic: unknown task, zero reward, and
// pot-short all refuse before any downstream effect.
func TestPokeRefusals(cur realm, t *testing.T) {
	adminSet(cur, TaskSubExpire, 0)
	testing.SetRealm(testing.NewUserRealm(poker))
	testing.SetOriginCaller(poker)
	testing.SetOriginSend(nil)
	uassert.AbortsContains(t, cur, "no reward configured", func() {
		PokeExpire(cross(cur), 0)
	})
	adminSet(cur, TaskSubExpire, 5000)

	testing.SetRealm(testing.NewUserRealm(poker))
	testing.SetOriginCaller(poker)
	testing.SetOriginSend(ugnot(5))
	uassert.AbortsWithMessage(t, cur, "this function does not accept coins", func() {
		PokeExpire(cross(cur), 0)
	})
	testing.SetRealm(testing.NewUserRealm(poker))
	testing.SetOriginCaller(poker)
	testing.SetOriginSend(ugnot(5))
	uassert.AbortsWithMessage(t, cur, "this function does not accept coins", func() {
		PokeExecute(cross(cur), "x")
	})
}

func TestClaims(cur realm, t *testing.T) {
	syncHeld()
	earned := BalanceOf(poker)
	if earned == 0 {
		t.Fatal("fixture: poker should have earnings")
	}
	before := coinsOf(poker)
	testing.SetRealm(testing.NewUserRealm(poker))
	testing.SetOriginCaller(poker)
	testing.SetOriginSend(nil)
	ClaimAll(cross(cur))
	if coinsOf(poker)-before != earned || BalanceOf(poker) != 0 {
		t.Fatal("claim did not move the earned balance")
	}
	testing.SetRealm(testing.NewUserRealm(mallory))
	testing.SetOriginCaller(mallory)
	testing.SetOriginSend(nil)
	uassert.AbortsWithMessage(t, cur, "nothing to claim", func() {
		ClaimAll(cross(cur))
	})
	uassert.AbortsContains(t, cur, "insufficient balance", func() {
		Claim(cross(cur), 1)
	})
	conserved(t)
}

func TestSweepReserve(cur realm, t *testing.T) {
	syncHeld()
	testing.SetRealm(testing.NewUserRealm(testAdmin))
	testing.SetOriginCaller(testAdmin)
	testing.SetOriginSend(nil)
	uassert.AbortsContains(t, cur, "no surplus to sweep", func() {
		SweepDenom(cross(cur), Denom)
	})
	testing.IssueCoins(Address(), ugnot(77))
	reserveBefore := Pot() + UsersTotal()
	got := coinsOf(testAdmin)
	testing.SetRealm(testing.NewUserRealm(testAdmin))
	testing.SetOriginCaller(testAdmin)
	testing.SetOriginSend(nil)
	SweepDenom(cross(cur), Denom)
	if coinsOf(testAdmin)-got != 77 {
		t.Fatal("sweep amount wrong")
	}
	if Pot()+UsersTotal() != reserveBefore {
		t.Fatal("sweep touched the reserve")
	}
	testing.SetRealm(testing.NewUserRealm(mallory))
	testing.SetOriginCaller(mallory)
	testing.SetOriginSend(nil)
	uassert.AbortsWithMessage(t, cur, "sweeper only", func() {
		SweepDenom(cross(cur), Denom)
	})
	conserved(t)
}

func TestAdminHandover(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(testAdmin))
	testing.SetOriginCaller(testAdmin)
	testing.SetOriginSend(nil)
	TransferAdmin(cross(cur), funder)
	testing.SetRealm(testing.NewUserRealm(mallory))
	testing.SetOriginCaller(mallory)
	testing.SetOriginSend(nil)
	uassert.AbortsWithMessage(t, cur, "only the staged successor may accept", func() {
		AcceptAdmin(cross(cur))
	})
	testing.SetRealm(testing.NewUserRealm(funder))
	testing.SetOriginCaller(funder)
	testing.SetOriginSend(nil)
	AcceptAdmin(cross(cur))
	if Admin() != funder {
		t.Fatal("authority did not move")
	}
	// Former admin locked out; sweeper moved with admin.
	testing.SetRealm(testing.NewUserRealm(testAdmin))
	testing.SetOriginCaller(testAdmin)
	testing.SetOriginSend(nil)
	uassert.AbortsWithMessage(t, cur, "admin only", func() {
		SetReward(cross(cur), TaskSubExpire, 1)
	})
	uassert.AbortsWithMessage(t, cur, "sweeper only", func() {
		SweepDenom(cross(cur), Denom)
	})
	// Hand back.
	testing.SetRealm(testing.NewUserRealm(funder))
	testing.SetOriginCaller(funder)
	testing.SetOriginSend(nil)
	TransferAdmin(cross(cur), testAdmin)
	testing.SetRealm(testing.NewUserRealm(testAdmin))
	testing.SetOriginCaller(testAdmin)
	testing.SetOriginSend(nil)
	AcceptAdmin(cross(cur))
}

func TestRender(t *testing.T) {
	out := Render("")
	if !strings.Contains(out, "sub_expire") || !strings.Contains(out, "timelock_execute") {
		t.Fatal("render missing task lines")
	}
	if Render("x") == Render("") {
		t.Fatal("unknown path fell through")
	}
}

// The BUBBLE treasury: where the pools' royalty lands, and the one power that moves it.
//
// Bubble Rumble's pools (v5 on) send 5 % of every boop to an address that belongs to the BUBBLE token realm and to
// nobody else: the token's SUB-realm for the kind published here, `treasury:spend`. A sub-realm is a distinct
// package path (`…/bubble#treasury-spend`) with its own address; it can hold and send coins and can never issue
// tokens. The token's governor hands exactly that sub-realm to this kind's Do when the holders have decided a
// spend, and to nothing else — so the only way a coin leaves the treasury is a proposal under `treasury:spend`,
// adopted by the holders (govern:adopt) and passed on the token's own money terms: a fifth of the supply turning
// out, two thirds yes, a week to vote, two days' delay.
//
// This realm holds no coins and no power of its own. It publishes the kind (Offer, at its deploy), says where the
// treasury is (Address), how much it holds (Balance) and renders the terms. The kind's Do runs inside the token
// realm and crosses back here with the sub-realm's own token to note each spend (noteSpend: the pace lives here);
// nothing else writes here, and what was spent is also on the chain (the TreasurySpend event).
package bubbletreasury

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"strconv"
	"strings"
	"time"

	governor "gno.land/p/g1leu8d2vsplhehcfkjg50mwgdpxdkt8tztu95wr/governor/v0"
	"gno.land/r/g1leu8d2vsplhehcfkjg50mwgdpxdkt8tztu95wr/bubble"
)

const (
	bubblePath = "gno.land/r/g1leu8d2vsplhehcfkjg50mwgdpxdkt8tztu95wr/bubble"
	ownPath    = "gno.land/r/g1leu8d2vsplhehcfkjg50mwgdpxdkt8tztu95wr/bubbletreasury"

	// KindName is what the holders adopt and propose under. The governor derives the sub-realm's path from it:
	// lower-cased, every character outside [a-z0-9] turned into '-' — so `treasury:spend` lives at `treasury-spend`.
	KindName = "treasury:spend"
	subpath  = "treasury-spend"

	one = int64(1_000_000) // ugnot in one GNOT

	// MaxSpend is the most one proposal may move, in whole GNOT — and never more than a QUARTER of what the treasury
	// holds (MaxShare), or SmallTreasury whole GNOT if that is more (so a small treasury can be spent whole, and a
	// treasury just over it has no cliff). The cap bounds one question; the PACE is the window: a window opens at
	// the first spend after Window seconds of none, and the spends in the Window seconds from that first spend
	// together may move at most that same quarter of what the treasury held then (spentAt/windowBase below); the
	// next spend after those seconds opens the next window. So "a quarter per two-day window" is true in code: a
	// majority that wants it all has to say so in public, and wait, several times over.
	MaxSpend      = int64(100_000)
	MaxShare      = int64(4)                // a proposal, and a window, may move at most balance/MaxShare…
	SmallTreasury = int64(40)               // …or this many whole GNOT, whichever is more (up to the balance)
	Window        = int64(2 * 24 * 60 * 60) // seconds: the pace — one quarter per window
)

// Offer, at deploy: the kind is published in the same transaction that stores this realm, so there is no window
// in which somebody else can bind the name first (r/bubble's Offer is open to anyone and a name, once taken, is
// taken for good). If the name IS taken by then, the deploy fails as a whole and this realm is redeployed under a
// name that maps to the same sub-path (see Recovery in the plan) — nothing has been paid to the address yet.
func init(cur realm) {
	bubble.Offer(cross(cur), spendKind{}, governor.BootstrapRules())
	offered = true
}

// poolRealms are the game's realms: a spend to one of their addresses would strand the coins (a realm's balance is
// not a bubble's pot), and "seed a bubble" is exactly the spend the holders will think of first.
var poolRealms = []string{
	"gno.land/r/g1leu8d2vsplhehcfkjg50mwgdpxdkt8tztu95wr/bubblerumble",
	"gno.land/r/g1leu8d2vsplhehcfkjg50mwgdpxdkt8tztu95wr/bubblerumble2",
	"gno.land/r/g1leu8d2vsplhehcfkjg50mwgdpxdkt8tztu95wr/bubblerumble3",
	"gno.land/r/g1leu8d2vsplhehcfkjg50mwgdpxdkt8tztu95wr/bubblerumble4",
	"gno.land/r/g1leu8d2vsplhehcfkjg50mwgdpxdkt8tztu95wr/bubblerumble5",
}

var (
	// treasury is the address the pools pay: the token realm's sub-realm for the kind. Pure arithmetic on the two
	// paths (chain.DerivePkgSubAddr), the same the VM does when the token realm runs the kind.
	treasury = chain.DerivePkgSubAddr(bubblePath, subpath)
	offered  bool
	// spentAt is the height of the last spend: ONE spend per block. The governor's own govern:batch runs every
	// member of a decided batch in one transaction, and each member's Check sees the balance before any of them
	// ran — so a ladder of quarter-sized lines (25, 18, 14, 10 … of 100) would pass every cap and drain the
	// treasury in one vote. A second spend in the block a spend already landed in aborts instead (Do panics: the
	// transaction unwinds, nothing moves, the proposal stays decided and runs in a later block); a batch of two
	// spends therefore never runs at all. So "a quarter at a time" means a quarter per vote, as it should.
	spentAt int64
	spends  int64 // spends executed, ever
	spent   int64 // ugnot moved out, ever
	// the window: opened by the first spend after Window seconds of none; what it may move is the cap for what the
	// treasury held then (windowBase), and windowSpent is what it has moved so far
	windowAt    int64 // block time the window opened
	windowBase  int64 // ugnot held when it opened, before its first spend
	windowSpent int64 // ugnot moved in it
)

// WindowLeft is what may still move before the window closes, in ugnot — the whole cap for a window not open.
func WindowLeft() int64 {
	now := time.Now().Unix()
	if windowAt == 0 || now-windowAt >= Window {
		return maxFor(Balance()) * one
	}
	left := maxFor(windowBase)*one - windowSpent
	if left < 0 {
		return 0
	}
	return left
}

// SpentAt is the height of the last spend; Spends and Spent, the count and the sum — the realm's own log.
func SpentAt() int64 { return spentAt }
func Spends() int64  { return spends }
func Spent() int64   { return spent }

// noteSpend is the kind's way to write here: Do runs inside the token realm, which cannot touch this realm's
// variables, so it crosses back with the sub-realm token it was handed — and only that token is let in
// (its address is the treasury). Called BEFORE the coins move; a second call in one block panics so the
// transaction, and with it any batch, unwinds with nothing moved.
func noteSpend(cur realm, amt int64) {
	if cur.Previous().Address() != treasury {
		panic("treasury: only the treasury's own kind may note a spend")
	}
	h := runtime.ChainHeight()
	if h == spentAt {
		panic("treasury: one spend per block — this block already has one; run it again in the next")
	}
	now := time.Now().Unix()
	if windowAt == 0 || now-windowAt >= Window {
		windowAt, windowBase, windowSpent = now, Balance(), 0 // Balance() is read before this spend's send
	}
	if windowSpent+amt > maxFor(windowBase)*one {
		panic("treasury: this window (" + strconv.FormatInt(Window/86400, 10) + " days) has moved its quarter already; run it again when the window has passed")
	}
	windowSpent += amt
	spentAt, spends, spent = h, spends+1, spent+amt
}

// Address is where the royalty goes. Every pool version from v5 pays here; anyone may send here.
func Address() address { return treasury }

// Balance is what the treasury holds right now, in ugnot.
func Balance() int64 { return banker.NewReadonlyBanker().GetCoins(treasury).AmountOf("ugnot") }

// Offered is whether the kind has been published to the token's governor.
func Offered() bool { return offered }

// Offer is the same publication for a realm loaded without its init having run it (a test harness): it does
// nothing once the token's governor knows the name. The holders still have to adopt the kind by vote before a spend
// can be proposed.
func Offer(cur realm) {
	if _, known := bubble.KindRules(KindName); known {
		offered = true
		return
	}
	bubble.Offer(cross(cur), spendKind{}, governor.BootstrapRules())
	offered = true
}

// MaxNow is the most one proposal may move right now, in whole GNOT: the cap for a balance.
func MaxNow() int64 { return maxFor(Balance()) }

func maxFor(balance int64) int64 {
	whole := balance / one
	m := whole / MaxShare
	if m < SmallTreasury {
		m = minInt(whole, SmallTreasury) // a small treasury may go whole; just over it, the same forty — no cliff
	}
	return minInt(m, MaxSpend)
}

func minInt(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
}

// Preview is what a proposal with this payload would say, and whether it could open now.
func Preview(payload string) string {
	k := spendKind{}
	s := k.Describe(payload)
	if err := k.Check(payload); err != nil {
		return s + " — refused: " + err.Error()
	}
	return s
}

// ---- the kind

type spendKind struct{}

func (spendKind) Name() string { return KindName }

// Describe reads the payload alone: two voters at different heights must see the same question.
func (spendKind) Describe(p string) string {
	to, n, err := parse(p)
	if err != nil {
		return "spend from the BUBBLE treasury: " + p
	}
	return "send " + strconv.FormatInt(n, 10) + " GNOT from the BUBBLE treasury to " + to.String()
}

// Check runs when the proposal opens and again right before Do: the amount must be within the cap both times.
func (spendKind) Check(p string) error {
	_, n, err := parse(p)
	if err != nil {
		return err
	}
	return within(n)
}

// within is the cap for the balance as it stands: the whole of a small treasury, a quarter of a large one.
func within(n int64) error {
	have := Balance()
	if n*one > have {
		return errf("the treasury holds " + gnot(have) + " GNOT, not " + strconv.FormatInt(n, 10))
	}
	if m := maxFor(have); n > m {
		return errf("one proposal may move at most " + strconv.FormatInt(m, 10) + " GNOT of the " + gnot(have) + " held (a quarter, or " + strconv.FormatInt(SmallTreasury, 10) + " whole GNOT if that is more)")
	}
	return nil
}

// Do moves the coins. rlm is the token realm's sub-realm for this kind, handed over by its governor for this one
// decided proposal: its address is the treasury, and RealmSend from it is the only send there is. An error ends
// the proposal as failed with nothing moved; nothing here can half-finish.
func (spendKind) Do(_ int, rlm realm, p string) error {
	to, n, err := parse(p)
	if err != nil {
		return err
	}
	if rlm.Address() != treasury {
		return errf("that is not the treasury's realm") // a governor other than the token's ran this kind
	}
	if err := within(n); err != nil {
		return err
	}
	amt, have := n*one, Balance()
	noteSpend(cross(rlm), amt) // one spend per block: a batch of spends aborts here (see spentAt)
	banker.NewBanker(banker.BankerTypeRealmSend, rlm).SendCoins(treasury, to, chain.Coins{{"ugnot", amt}})
	chain.Emit("TreasurySpend", "to", to.String(), "ugnot", strconv.FormatInt(amt, 10), "left", strconv.FormatInt(have-amt, 10))
	return nil
}

// parse reads "g1… N": an address and whole GNOT, 1 ≤ N ≤ MaxSpend.
func parse(p string) (address, int64, error) {
	parts := strings.Fields(p)
	if len(parts) != 2 {
		return "", 0, errf("expected \"g1… N\": an address and whole GNOT")
	}
	to := address(parts[0])
	if !to.IsValid() {
		return "", 0, errf("not an address")
	}
	if to == treasury || to == chain.PackageAddress(bubblePath) || to == chain.PackageAddress(ownPath) {
		return "", 0, errf("that is a realm of the token's own: coins sent there could never come back")
	}
	for _, r := range poolRealms { // a pool realm's address takes coins into no pool: they would sit there for good
		if to == chain.PackageAddress(r) {
			return "", 0, errf("that is a pool realm's own address: coins sent there join no bubble and never come back (seed a bubble with CreatePool, from a wallet)")
		}
	}
	n, err := strconv.ParseInt(parts[1], 10, 64)
	if err != nil || n <= 0 || n > MaxSpend {
		return "", 0, errf("expected whole GNOT, between 1 and " + strconv.FormatInt(MaxSpend, 10) + " in one proposal")
	}
	return to, n, nil
}

type treasuryErr struct{ msg string }

func (e *treasuryErr) Error() string { return "treasury: " + e.msg }
func errf(s string) error            { return &treasuryErr{s} }

// gnot prints ugnot as GNOT with up to six decimals, trailing zeros dropped.
func gnot(u int64) string {
	whole, frac := u/one, u%one
	if frac == 0 {
		return strconv.FormatInt(whole, 10)
	}
	f := strconv.FormatInt(frac, 10)
	for len(f) < 6 {
		f = "0" + f
	}
	return strconv.FormatInt(whole, 10) + "." + strings.TrimRight(f, "0")
}

// Render: the treasury for a reader — where, how much, and how it moves.
func Render(path string) string {
	if path == "json" {
		return `{"address":"` + treasury.String() + `","ugnot":` + strconv.FormatInt(Balance(), 10) + `,"kind":"` + KindName + `","offered":` + strconv.FormatBool(offered) + `,"maxSpend":` + strconv.FormatInt(MaxSpend, 10) + `,"maxNow":` + strconv.FormatInt(MaxNow(), 10) + `,"windowLeft":` + strconv.FormatInt(WindowLeft(), 10) + `,"spends":` + strconv.FormatInt(spends, 10) + `,"spent":` + strconv.FormatInt(spent, 10) + `}`
	}
	var b strings.Builder
	b.WriteString("# The BUBBLE treasury\n\n")
	b.WriteString("**" + gnot(Balance()) + " GNOT** at `" + treasury.String() + "` — the token realm's own sub-realm `" + subpath + "`.\n\n")
	b.WriteString("Every Bubble Rumble pool from v5 on sends **5% of every boop's bid** here (not of a bubble's seed, not of shots). Nothing leaves except by a decided vote of the BUBBLE holders under `" + KindName + "`")
	if offered {
		b.WriteString(" (published to the token's governor; the holders adopt it with `govern:adopt`, then anyone may propose `\"g1… N\"` — an address and whole GNOT)")
	} else {
		b.WriteString(" (not yet published: call `Offer` once)")
	}
	b.WriteString(". A proposal may move at most a quarter of what the treasury holds, or " + strconv.FormatInt(SmallTreasury, 10) + " GNOT if that is more, never over " + strconv.FormatInt(MaxSpend, 10) + " — right now " + strconv.FormatInt(MaxNow(), 10) + " GNOT; and the spends in a window — the " + strconv.FormatInt(Window/86400, 10) + " days from its first spend — together may move that same quarter (or " + strconv.FormatInt(SmallTreasury, 10) + ") of what it held then (" + gnot(WindowLeft()) + " GNOT left in the window now); the next spend after those days opens the next window; one spend a block, so a batch of spends cannot run. A quarter per two-day window, whatever is proposed. Only the holders' votes move money, on the token's money terms: a fifth of the supply turning out (this kind takes the plain fifth; the token's own settings raise their bar with past turnout), two thirds yes, a week to vote (or sooner, once the outcome cannot change), two days' delay, a fortnight to run it. Votes count what a wallet held at the last sealed epoch before the question opened. Today the founding share (10,000,000 of the BUBBLE in issue) carries every vote; that thins as referrals mint.\n\n")
	b.WriteString("BUBBLE carries a vote, not a claim: nothing here promises holders a payment from the treasury, and the holders' custom is prizes, work on the game and the token's market. Spends so far: " + strconv.FormatInt(spends, 10) + ", " + gnot(spent) + " GNOT.\n\n")
	b.WriteString("Replacing this kind: a kind under another name that the governor maps to the same sub-path `" + subpath + "` (for example `treasury/spend` or `treasury.spend`) spends from the same address once adopted; a name that maps elsewhere is a new, empty treasury. Anyone may offer a look-alike name: before adopting one, read who offered it (the KindOffered event) and its code.\n")
	return b.String()
}

// Package bubblerumble5 is the fifth Bubble Rumble realm: v4's game whole, with
// one new slice. Of every bid 50% goes to the pot, 30% is credited at once to the
// pool's earlier bidders pro-rata to what they paid in, 10% to whoever invited the
// bidder, 5% to the pool's creator — and 5% to the BUBBLE treasury: the token
// realm's own sub-realm (bubbletreasury), which nothing moves but a decided vote
// of the BUBBLE holders. The five percent comes out of the pot's share alone; the
// dividends, the inviter's and the creator's slices are v4's. Seeds (a creator's
// own money into a new pool) and shots pay no royalty: a seed is a gift to the
// players, and a shot's losing side already feeds the pot. Every pool has a last
// day, a flag war at the close, credited earnings and Withdraw, a clock that can
// be bought down but never under MinClock, and the shot that can win the pot:
//
//   - A shot is still extra money on a bid, a chance to pop the bubble at once.
//     The chance is 0.8 × shot / take, at most 1% a shot, where the take is what
//     a pop would pay the shooter right now: the pot less the team's 35%, times the
//     winner's live share (LiveBps). So the pot keeps a fifth of every shot's fair
//     value however far the last day has slid, and a hit pops the bubble: the pool
//     closes with the shooter as its winner and Claim pays it as any pop.
//   - The draw's randomness is a commit-reveal by the keeper — the operator's own
//     box, which also settles pools on time. The keeper publishes sha256 hashes of
//     secrets ahead of time (Commit); a bid with a shot takes the next unused one;
//     the shot is drawn when someone (the keeper, or anyone) reveals that secret
//     (Reveal) in the blocks ShotDelay to ShotDelay+ShotWindow after the bid. The
//     seed is the secret with the shot's own facts and the reveal block's height
//     and time. Nobody without the secret can grind it: not the shooter, not a
//     validator. The secret's holder knows the two candidate block times a block
//     ahead and may pick which of the window's three blocks to reveal in — three
//     rolls, at most 2.4× fair on a 1% shot — which is why the keeper key never
//     bids or shoots, and its operator never shoots. (The site's own keep-alive boops come from another key and
//     pay the royalty like any boop; for the operator, who votes the treasury,
//     that slice is a wash — said here so nobody has to work it out.)
//   - A shot not revealed in its window, or on a pool that closed first, is void:
//     it goes into the pot and counts as a miss, as in v3. Nothing is refunded, so
//     withholding a reveal never pays whoever withholds it. What remains is that a
//     keeper who leads a pot could withhold a stranger's hit and let the money fall
//     into the pot it leads: refused shots are counted on the pool for all to see,
//     and so are reveals that came in the window's later blocks (the honest keeper
//     always reveals at the first), so a keeper choosing its block would show.
//   - Shots are sold only while the keeper is alive: a shot needs a free commitment
//     and a sign of life (Commit or Heartbeat) within KeeperFresh. Otherwise the bid
//     stands and the shot's money goes straight back in the same transaction.
//   - Shots are refused in the last quarter of a pool's life (which also keeps every
//     reveal window clear of the last day) and under MinShot. RevealTip is taken
//     from every shot and credited to the keeper whoever sends the reveal (the
//     secret sits in the mempool, and a proposer could copy it), so the keeper
//     pays for itself. The keeper's own shots are refused outright.
//   - Reveals go in shot order, so among two pending shots nobody chooses which pops.
//
// Residuals, stated plainly: the secret holder's three rolls; the keeper-defender
// veto above; a proposer who reads the keeper's reveal in the mempool holds the
// secret too, and proposing the window's blocks could drop the reveal for a roll
// it does not like or leave it out altogether (a void), which Late and Voided
// show; keeper and validator together could grind. SetShots is the switch if any
// of it is seen. SetKeeper drops every unused commitment.
package bubblerumble5

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"crypto/sha256"
	"encoding/binary"
	"encoding/hex"
	"math"
	"math/bits"
	"strconv"
	"strings"
	"time"
)

const (
	MinWindow    int64 = 10                // seconds
	MaxWindow    int64 = 30 * 24 * 3600    // 30 days
	MinLife      int64 = 3600              // an hour
	MaxLife      int64 = 30 * 24 * 3600    // 30 days
	MinBasePrice int64 = 1_000             // ugnot, 0.001 GNOT
	MaxBasePrice int64 = 1_000_000_000_000 // ugnot, 1,000,000 GNOT
	MaxNameLen         = 40
	HistoryLen         = 50  // bids kept per pool for the feed
	RosterMax          = 100 // distinct bidders a pool pays dividends, team shares and the close split to
	MaxBoost     int64 = 10  // the shortest clock a bid can buy is window/MaxBoost...
	MinClock     int64 = 300 // ...and never under five minutes: people must be able to answer

	// where every bid goes, in percent
	PotShare      int64 = 50
	DivShare      int64 = 30 // to earlier bidders of the pool, pro-rata by weight
	RefShare      int64 = 10 // to the bidder's inviter
	CreatorShare  int64 = 5
	TreasuryShare int64 = 5 // to the BUBBLE treasury: the token realm's sub-realm, spent only by the holders' vote
	// of the pot at the close, to the other bidders under the winner's flag
	TeamShare int64 = 35

	ShotMaxBps    int64 = 100     // 1% a shot, whatever is paid
	ShotFair      int64 = 8000    // chance in bps = ShotFair × shot / take (0.8 of fair odds)
	ShotDelay     int64 = 3       // blocks after the shot was paid for before it can be revealed...
	ShotWindow    int64 = 2       // ...and how many more blocks it may still be revealed in: three blocks, as v3 drew; three rolls at most for the secret's holder
	MinShot       int64 = 100_000 // ugnot: no shot under 0.1 GNOT, so dust cannot make reveals cost more than they tip
	RevealTip     int64 = 20_000  // ugnot: off every shot, to whoever reveals it
	KeeperFresh   int64 = 300     // seconds: shots are sold only this soon after the keeper's last sign of life (it heartbeats every two minutes)
	LiveFloor     int64 = 2500    // bps: no shots once the winner's live share has slid under a quarter (which also keeps every reveal window clear of the last day)
	MaxCommits          = 500     // unused commitments the queue holds at most
	CommitBatch         = 100     // hashes one Commit may bring
	CommitCompact       = 200     // used commitments kept before the queue is compacted
)

// admin is the realm's deployer: the only address that may turn shots off.
const admin = address("g1leu8d2vsplhehcfkjg50mwgdpxdkt8tztu95wr")

// pkgPath must match gnomod.toml: the realm's own address derives from it.
const pkgPath = "gno.land/r/g1leu8d2vsplhehcfkjg50mwgdpxdkt8tztu95wr/bubblerumble5"

// The BUBBLE treasury is the token realm's sub-realm for its `treasury:spend` kind (the realm bubbletreasury
// publishes the kind and says the same address): a distinct address the token's governor alone can spend from,
// after a vote of the holders. Derived here from the two paths, as the chain derives it.
const (
	bubblePath      = "gno.land/r/g1leu8d2vsplhehcfkjg50mwgdpxdkt8tztu95wr/bubble"
	treasurySubpath = "treasury-spend"
)

type Entry struct {
	N      int64
	Bidder address
	Flag   string
	Price  int64 // what was paid for the bid itself; at least the price at the time
	Shot   int64 // extra paid for a chance to pop the bubble
	Clock  int64 // seconds this bid had to stand
	Pot    int64 // pot right after this bid
	At     time.Time
}

// Member is a distinct bidder of a pool: dividends, team shares and the close
// split go to the roster. The flag is the one flown at the first bid here.
type Member struct {
	Addr   address
	Flag   string
	Paid   int64 // gross paid into this pool (bids and shots)
	Earned int64 // dividends received from this pool
}

// Shot is a shot at the bubble waiting to be revealed, or resolved.
type Shot struct {
	N        int64 // 1-based within the pool
	Bidder   address
	Paid     int64  // ugnot paid for it (the tip comes out of this at the reveal)
	Take     int64  // what a pop would have paid the shooter when the odds were set
	Bps      int64  // chance, in basis points
	CommitH  int64  // block height when paid; revealable at CommitH+ShotDelay and the ShotWindow blocks after
	Hash     string // the commitment it took: sha256 of the secret that decides it, 32 raw bytes
	Resolved bool
	Won      bool
	Void     bool // not revealed in its window, or the pool closed first: a miss
	DrawH    int64
	Revealer address
}

type Pool struct {
	ID           int64
	Name         string
	Creator      address
	Window       int64 // seconds the last bid must stand to win
	Life         int64 // seconds from the first bid to the last day
	BasePrice    int64 // ugnot; the Nth bid costs BasePrice·√N
	Seed         int64
	Pot          int64
	Bids         int64
	LastBidder   address
	LastBidAt    time.Time
	FirstBidAt   time.Time
	Clock        int64 // seconds the current top bid has to stand
	CreatedAt    time.Time
	Paid         bool // the pot went out, or the seed back to the creator
	Cancelled    bool
	Popped       bool // a shot ended it
	PoppedAt     time.Time
	DivPaid      int64 // dividends paid out of this pool so far
	RefPaid      int64
	CreatorPaid  int64
	TreasuryPaid int64 // the BUBBLE treasury's 5% of this pool's bids
	ShotPaid     int64 // slices paid to hits while the pool went on
	Misses       int64 // shots resolved and lost, voids included: the scars on the bubble
	Voided       int64 // of those, the shots nobody revealed in time
	Late         int64 // shots revealed in their window but not at its first block: a keeper choosing its block would show here
	ShotEscrow   int64 // shots paid for and not yet resolved: in the pot once they are
	WinnerFlag   string
	TeamPaid     int64 // what the winner's team received at the close
	SharedPaid   int64 // the pro-rata part of the close
	WinnerPaid   int64
	History      []Entry
	Roster       []*Member
	Shots        []*Shot
	Settled      int // shots before this index are all resolved (they resolve strictly in order): where settleShots starts
}

// Player is what the realm remembers about an address across pools.
type Player struct {
	Referrer  address // set by the first bid, permanent
	Recruits  int64
	Flag      string
	Bids      int64
	Paid      int64
	DivEarned int64
	RefEarned int64
	Won       int64 // pots, team shares, close splits and shot slices received
	Shots     int64
	Hits      int64
	Owed      int64 // credited and not yet withdrawn
	Withdrawn int64
}

var (
	shotsOn      = true
	keeper       address   // who commits and heartbeats (SetKeeper); the admin may too
	keeperSeen   time.Time // the keeper's last Commit or Heartbeat
	commits      []string  // the hashes of the keeper's secrets (32 raw bytes each), in order; the first head are used
	head         int
	voided       int64 // shots voided over all pools
	late         int64 // shots revealed after the first block of their window, over all pools
	pools        []*Pool
	players      = map[address]*Player{}
	teamPaid     = map[string]int64{} // flag -> gross bid volume under it
	teamWon      = map[string]int64{} // flag -> pots closed under it
	teamSize     = map[string]int64{} // flag -> players flying it
	realmAddr    = chain.PackageAddress(pkgPath)
	treasuryAddr = chain.DerivePkgSubAddr(bubblePath, treasurySubpath)
	treasuryPaid int64 // the royalty over all pools
)

// TreasuryAddr is where 5% of every bid goes: the BUBBLE treasury.
func TreasuryAddr() address { return treasuryAddr }

// TreasuryPaid is what every pool of this realm has sent there.
func TreasuryPaid() int64 { return treasuryPaid }

// Price of the next bid in a pool with the given base price and n bids so far.
func Price(base, n int64) int64 {
	return int64(math.Ceil(float64(base) * math.Sqrt(float64(n+1))))
}

// LastDay is when the pool's life runs out; zero before the first bid.
func (p *Pool) LastDay() time.Time {
	if p.FirstBidAt.IsZero() {
		return time.Time{}
	}
	return p.FirstBidAt.Add(time.Duration(p.Life) * time.Second)
}

// Deadline is when the pool closes if nothing changes: the clock or the last
// day, whichever comes first; the pop, if a shot ended it.
func (p *Pool) Deadline() time.Time {
	if p.Popped {
		return p.PoppedAt
	}
	d := p.LastBidAt.Add(time.Duration(p.Clock) * time.Second)
	if last := p.LastDay(); !last.IsZero() && last.Before(d) {
		return last
	}
	return d
}

func (p *Pool) Over() bool       { return p.Bids > 0 && (p.Popped || !time.Now().Before(p.Deadline())) }
func (p *Pool) NextPrice() int64 { return Price(p.BasePrice, p.Bids) }

// LiveBps is how much of the pot still goes the winner's way, in basis points
// of the pot: 10000 at the first bid, sliding to 0 on the last day. Frozen at
// the close.
func (p *Pool) LiveBps() int64 {
	if p.FirstBidAt.IsZero() || p.Life <= 0 {
		return 10000
	}
	at := time.Now()
	if p.Over() {
		at = p.Deadline()
	}
	elapsed := at.Unix() - p.FirstBidAt.Unix()
	if elapsed <= 0 {
		return 10000
	}
	if elapsed >= p.Life {
		return 0
	}
	return 10000 * (p.Life - elapsed) / p.Life
}

// ClockFor is the clock a bid buys by paying sent against a price: the window
// divided by the multiple paid, never below window/MaxBoost.
func ClockFor(window, price, sent int64) int64 {
	c := int64(float64(window) * float64(price) / float64(sent))
	if c < window/MaxBoost {
		c = window / MaxBoost
	}
	if c < MinClock {
		c = MinClock
	}
	if c > window {
		c = window
	}
	return c
}

// mulDiv is a×b/c without overflowing on the way: pots and paid-ins are both
// in ugnot and their product passes int64 at a few thousand GNOT each.
func mulDiv(a, b, c int64) int64 {
	if a < 0 || b < 0 || c <= 0 {
		panic("mulDiv: negative")
	}
	hi, lo := bits.Mul64(uint64(a), uint64(b))
	if hi >= uint64(c) {
		panic("mulDiv: overflow")
	}
	q, _ := bits.Div64(hi, lo, uint64(c))
	return int64(q)
}

// ShotBps is the chance a shot buys against what a pop would pay, in basis points.
func ShotBps(shot, take int64) int64 {
	if shot <= 0 || take <= 0 {
		return 0
	}
	bps := ShotFair * shot / take
	if bps > ShotMaxBps {
		bps = ShotMaxBps
	}
	return bps
}

// Take is the most a pop could pay this shooter if the pool closed now on a pot
// of this size: Claim's own arithmetic, run dry, with the team's share counted
// as the shooter's too — one bid from a friend (or a second address) under a
// flag nobody else flies collects it, so the odds must assume it is collected.
// What is not the shooter's is the slide: the part of the rest that the last
// day has moved to the whole roster by paid-in.
func (p *Pool) Take(shooter address, pot int64) int64 {
	toWinner, cut := p.payout(shooter, pot, false)
	return toWinner + cut
}

// CreatePool opens a pool. Any ugnot sent with the call seeds its pot. The
// creator earns CreatorShare of every bid. life is the pool's life in seconds
// from its first bid; 0 means ten windows (at least an hour, at most 30 days).
func CreatePool(cur realm, name string, window int64, basePrice int64, life int64) int64 {
	creator := userCaller(cur)
	name = cleanName(name)
	if window < MinWindow || window > MaxWindow {
		panic("window must be between 10s and 30d")
	}
	if basePrice < MinBasePrice || basePrice > MaxBasePrice {
		panic("base price must be between 0.001 and 1,000,000 GNOT")
	}
	if life == 0 { // ten windows of fighting, within the bounds
		life = 10 * window
		if life < MinLife {
			life = MinLife
		}
		if life > MaxLife {
			life = MaxLife
		}
	}
	if life < MinLife || life > MaxLife {
		panic("life must be between 1h and 30d")
	}
	if life < window {
		panic("life must be at least the window")
	}
	seed := ugnotSent()
	p := newPool(name, creator, window, basePrice, life, seed)
	chain.Emit("PoolCreated", "id", itoa(p.ID), "creator", creator.String(), "seed", itoa(seed))
	return p.ID
}

func newPool(name string, creator address, window, basePrice, life, seed int64) *Pool {
	p := &Pool{
		ID: int64(len(pools)) + 1, Name: name, Creator: creator, Window: window, Life: life,
		BasePrice: basePrice, Seed: seed, Pot: seed, CreatedAt: time.Now(),
	}
	pools = append(pools, p)
	return p
}

// Bid pays at least the current price and resets the clock. ref is the address
// that invited the bidder ("" for none; only the first bid ever sets it), flag
// a two-letter country to play under ("" keeps the last one; the flag is locked
// per pool at the first bid there), shot how much of the money sent is a shot
// at popping the bubble (0 for none): the rest must cover the price, and paying
// more than the price shortens the clock.
func Bid(cur realm, id int64, ref string, flag string, shot int64) {
	bidder := userCaller(cur)
	p := pool(id)
	sent := ugnotSent()
	if p.Cancelled {
		panic("pool was cancelled")
	}
	// a pool that closed (or popped) since the bidder looked: the money goes back
	if p.Over() {
		if sent > 0 {
			send(cur, bidder, sent)
			chain.Emit("Refund", "id", itoa(id), "to", bidder.String(), "ugnot", itoa(sent))
		}
		if p.Popped {
			return
		}
		panic("pool is closed")
	}
	if shot < 0 || shot > sent {
		panic("shot must be between 0 and the amount sent")
	}
	price := p.NextPrice()
	bid := sent - shot
	if bid < price {
		panic("send at least " + itoa(price) + "ugnot for the bid, got " + itoa(bid) + "ugnot")
	}
	// shots of earlier bids whose window has passed are settled first
	p.settleShots()
	pl := player(bidder)
	if f := cleanFlag(flag); f != "" && f != pl.Flag {
		if pl.Flag != "" {
			teamSize[pl.Flag]--
		}
		pl.Flag = f
		teamSize[f]++
	}
	if pl.Referrer == "" && ref != "" {
		r := address(ref)
		if r.IsValid() && r != bidder {
			pl.Referrer = r
			player(r).Recruits++
		}
	}

	// where the bid goes
	div, refCut, creatorCut, royalty := bid*DivShare/100, bid*RefShare/100, bid*CreatorShare/100, bid*TreasuryShare/100
	toPot := bid - div - refCut - creatorCut - royalty // the dust of the four divisions stays in the pot
	if creatorCut > 0 {
		send(cur, p.Creator, creatorCut)
		p.CreatorPaid += creatorCut
	}
	if royalty > 0 { // the BUBBLE treasury's share, sent now like the creator's and the inviter's
		send(cur, treasuryAddr, royalty)
		p.TreasuryPaid += royalty
		treasuryPaid += royalty
	}
	if pl.Referrer != "" && refCut > 0 {
		send(cur, pl.Referrer, refCut)
		p.RefPaid += refCut
		player(pl.Referrer).RefEarned += refCut
	} else {
		toPot += refCut
	}
	divPaid := div - p.payDividends(cur, bidder, div)
	toPot += div - divPaid
	p.Pot += toPot

	m := p.member(bidder, pl.Flag)
	if m.Flag == "" { // a flagless first bid does not lock "no flag": the first flag flown here does
		m.Flag = pl.Flag
	}
	// the shot, if there can be one: else its money goes straight back and the bid stands
	why := ""
	if shot > 0 {
		why = p.shotRefusal(bidder, shot)
	}
	m.Paid += sent
	pl.Bids++
	pl.Paid += sent
	if pl.Flag != "" {
		teamPaid[pl.Flag] += sent
	}
	// the odds, on the pool as it stands with this bid booked (the shooter's own paid-in weighs in the slide):
	// priced here once, and a shot that buys no chance at all is refused like the rest
	var take, bps int64
	if shot > 0 && why == "" {
		take = p.Take(bidder, p.Pot+shot-RevealTip) // the pot a pop would pay from: this bid's share in, the shot itself in, the tip out
		bps = ShotBps(shot-RevealTip, take)
		if bps == 0 {
			why = "too small for any chance at this pot"
		}
	}
	if why != "" {
		m.Paid -= shot
		pl.Paid -= shot
		if pl.Flag != "" {
			teamPaid[pl.Flag] -= shot
		}
		send(cur, bidder, shot)
		chain.Emit("ShotReturned", "id", itoa(id), "bidder", bidder.String(), "ugnot", itoa(shot), "why", why)
		sent -= shot
		shot = 0
	}
	p.Bids++
	if p.FirstBidAt.IsZero() {
		p.FirstBidAt = time.Now()
	}
	p.LastBidder = bidder
	p.LastBidAt = time.Now()
	p.Clock = ClockFor(p.Window, price, bid)
	p.History = append(p.History, Entry{N: p.Bids, Bidder: bidder, Flag: m.Flag, Price: bid, Shot: shot, Clock: p.Clock, Pot: p.Pot, At: p.LastBidAt})
	if len(p.History) > HistoryLen {
		p.History = p.History[len(p.History)-HistoryLen:]
	}
	chain.Emit("Bid", "id", itoa(id), "n", itoa(p.Bids), "bidder", bidder.String(), "paid", itoa(bid), "shot", itoa(shot), "pot", itoa(p.Pot), "div", itoa(divPaid), "treasury", itoa(royalty))

	if shot > 0 {
		t := &Shot{N: int64(len(p.Shots)) + 1, Bidder: bidder, Paid: shot, Take: take, Bps: bps, CommitH: runtime.ChainHeight(), Hash: commits[head]}
		head++
		p.Shots = append(p.Shots, t)
		p.ShotEscrow += shot
		pl.Shots++
		chain.Emit("Shot", "id", itoa(id), "shot", itoa(t.N), "bidder", bidder.String(), "paid", itoa(shot), "take", itoa(take), "bps", itoa(bps), "commit", hex.EncodeToString([]byte(t.Hash)), "revealAt", itoa(t.CommitH+ShotDelay))
	}
}

// shotRefusal is why a shot cannot be sold on this pool right now ("" when it
// can): the checks a bid runs before taking one, in the order the page shows.
// The odds themselves are checked by the caller, on the booked state.
func (p *Pool) shotRefusal(shooter address, shot int64) string {
	switch {
	case !shotsOn:
		return "shots are off"
	case keeper != "" && shooter == keeper:
		return "the keeper never shoots"
	case shot < MinShot:
		return "under the smallest shot, " + GNOT(MinShot)
	case head >= len(commits):
		return "no commitment free: the keeper is away"
	case keeperSeen.IsZero() || time.Now().Unix()-keeperSeen.Unix() > KeeperFresh:
		return "the keeper has not been seen for " + dur(KeeperFresh)
	case p.LiveBps() < LiveFloor:
		return "the winner's share has slid under a quarter"
	}
	return ""
}

// SetShots turns shots off (or on again); only the deployer may.
func SetShots(cur realm, on bool) {
	if userCaller(cur) != admin {
		panic("only the deployer")
	}
	shotsOn = on
	chain.Emit("Shots", "on", jbool(on))
}

// SetKeeper names the address that commits and heartbeats; only the deployer
// may. Every unused commitment is dropped with it: a rotated or compromised
// keeper's secrets never decide a shot.
func SetKeeper(cur realm, addr address) {
	if userCaller(cur) != admin {
		panic("only the deployer")
	}
	if !addr.IsValid() {
		panic("bad address")
	}
	keeper = addr
	commits = commits[:head]
	chain.Emit("Keeper", "addr", addr.String())
}

func keeperCaller(cur realm) address {
	who := userCaller(cur)
	if who == "" || who != keeper {
		panic("only the keeper")
	}
	return who
}

func keeperOrAdmin(cur realm) address {
	who := userCaller(cur)
	if who != admin && (who == "" || who != keeper) {
		panic("only the keeper or the deployer")
	}
	return who
}

// Heartbeat is the keeper's sign of life: shots are sold only within
// KeeperFresh of the last one (a Commit counts too).
func Heartbeat(cur realm) {
	keeperCaller(cur)
	keeperSeen = time.Now()
}

// Commit queues the hashes of secrets the keeper will reveal later, in order,
// as a comma-separated list of 64 hex characters each; only the keeper, whose
// box holds the secrets. A hash still in the queue (used or not) is refused: a
// repeated secret would be public after its first reveal (a safety net against
// the keeper repeating itself; compaction forgets the oldest). The queue holds
// at most MaxCommits unused; the used ones in front of it are compacted away
// past CommitCompact.
func Commit(cur realm, hashes string) {
	keeperCaller(cur)
	keeperSeen = time.Now()
	parts := strings.Split(hashes, ",")
	if len(parts) == 0 || len(parts) > CommitBatch {
		panic("1 to " + strconv.Itoa(CommitBatch) + " hashes")
	}
	if len(commits)-head+len(parts) > MaxCommits {
		panic("the queue holds " + strconv.Itoa(MaxCommits) + " unused commitments at most")
	}
	if head > CommitCompact {
		commits = append([]string(nil), commits[head:]...)
		head = 0
	}
	for _, part := range parts {
		b, err := hex.DecodeString(strings.TrimSpace(part))
		if err != nil || len(b) != 32 {
			panic("a hash is 64 hex characters")
		}
		h := string(b)
		for _, c := range commits { // a safety net against the keeper repeating itself, over what the queue still holds
			if c == h {
				panic("hash already committed: " + part)
			}
		}
		commits = append(commits, h)
	}
	chain.Emit("Commit", "n", itoa(int64(len(parts))), "free", itoa(int64(len(commits)-head)))
}

// Retire drops the first n unused commitments: a keeper that lost the secrets
// behind them (the box rebuilt, the file gone) clears them so shots can go on.
// The deployer may too. It is not a sign of life.
func Retire(cur realm, n int64) {
	keeperOrAdmin(cur)
	if n <= 0 {
		panic("retire at least one")
	}
	if int(n) > len(commits)-head {
		n = int64(len(commits) - head)
	}
	commits = append(commits[:head], commits[head+int(n):]...)
	chain.Emit("Retire", "n", itoa(n), "free", itoa(int64(len(commits)-head)))
}

// Reveal draws shots with the secrets behind their commitments: a comma-separated
// list of pool:shot:secretHex, any pools, in one transaction — the keeper sends
// every shot that is due in one call, so a run of shots on one block never
// outpaces it. Anyone may call it; the secret is the proof, and the caller is
// tipped RevealTip out of each shot revealed. Shots go in order: an earlier one
// still pending must come first (in the list, or before). An entry not yet due
// is skipped, one with a wrong secret or already resolved is skipped with an
// event, so a stale entry never voids the rest; a malformed one (no such pool
// or shot, a cancelled pool, not pool:shot:secret) aborts the whole call, which
// only the keeper's own bug could send. The reveal must land in the
// blocks CommitH+ShotDelay through CommitH+ShotDelay+ShotWindow; later, or on a
// pool that has closed, the shot is already void (settleShots runs first): into
// the pot as a miss. A hit pops the bubble: the pool closes now with the shooter
// as its winner, settled at Claim.
func Reveal(cur realm, reveals string) {
	who := userCaller(cur)
	h := runtime.ChainHeight()
	done := 0
	for _, entry := range strings.Split(reveals, ",") {
		f := strings.Split(strings.TrimSpace(entry), ":")
		if len(f) != 3 {
			panic("each entry is pool:shot:secret")
		}
		id, n := parseID(f[0]), parseNum(f[1])
		p := pool(id)
		if p.Cancelled {
			panic("pool was cancelled")
		}
		p.settleShots()
		if n < 1 || int(n) > len(p.Shots) {
			panic("no such shot")
		}
		t := p.Shots[n-1]
		if t.Resolved || (n > 1 && !p.Shots[n-2].Resolved) {
			chain.Emit("RevealSkipped", "id", itoa(id), "shot", itoa(n), "why", jif(t.Resolved, "resolved", "earlier shot pending"))
			continue
		}
		if h < t.CommitH+ShotDelay {
			continue // not due yet: the keeper sends a block early to be sure of the window
		}
		secret, err := hex.DecodeString(strings.TrimSpace(f[2]))
		sum := sha256.Sum256(secret)
		if err != nil || string(sum[:]) != t.Hash {
			chain.Emit("RevealSkipped", "id", itoa(id), "shot", itoa(n), "why", "wrong secret")
			continue
		}
		// (a shot past its window, or on a pool that closed, was voided by settleShots above and skipped as resolved)
		done++
		t.Resolved, t.DrawH, t.Revealer = true, h, who
		p.ShotEscrow -= t.Paid
		// the tip is the keeper's whoever sent the reveal: the secret sits in the mempool, and a proposer could
		// copy it into a reveal of its own; the seed does not care who reveals, so nothing else changes
		tip := RevealTip
		if tip > t.Paid {
			tip = t.Paid
		}
		if keeper != "" {
			credit(keeper, tip)
		} else {
			credit(who, tip)
		}
		p.Pot += t.Paid - tip
		if h > t.CommitH+ShotDelay { // revealed in the window but not at its first block: the honest keeper's tell, counted
			p.Late++
			late++
		}
		t.Won = shotHits(seedFor(id, t, secret, h), t.Bps)
		chain.Emit("Revealed", "id", itoa(id), "shot", itoa(n), "bidder", t.Bidder.String(), "hit", jbool(t.Won), "bps", itoa(t.Bps), "by", who.String())
		if !t.Won {
			p.Misses++
			continue
		}
		player(t.Bidder).Hits++
		p.Popped, p.PoppedAt, p.LastBidder = true, time.Now(), t.Bidder
		chain.Emit("Popped", "id", itoa(id), "by", t.Bidder.String(), "pot", itoa(p.Pot))
	}
	if done == 0 {
		panic("nothing revealed")
	}
}

// Settle voids the shots at a pool that nobody revealed in time, or that its
// close overtook. Anyone may call it; every bid, reveal and claim on the pool
// does the same first.
func Settle(cur realm, id int64) {
	pool(id).settleShots()
}

// settleShots voids, in order, every pending shot whose window has passed or
// whose pool is over: the shot's money goes into the pot and counts as a miss;
// nobody is tipped.
func (p *Pool) settleShots() {
	h := runtime.ChainHeight()
	over := p.Over()
	for p.Settled < len(p.Shots) && p.Shots[p.Settled].Resolved {
		p.Settled++
	}
	for _, t := range p.Shots[p.Settled:] {
		if t.Resolved || (h <= t.CommitH+ShotDelay+ShotWindow && !over) {
			continue
		}
		t.Resolved, t.Void, t.DrawH = true, true, h
		p.ShotEscrow -= t.Paid
		p.Pot += t.Paid
		p.Misses++
		p.Voided++
		voided++
		chain.Emit("Voided", "id", itoa(p.ID), "shot", itoa(t.N), "bidder", t.Bidder.String(), "why", jif(over, "closed", "unrevealed"))
	}
}

func jif(c bool, a, b string) string {
	if c {
		return a
	}
	return b
}

// seedFor is the draw's seed: the secret with the shot's own facts and the
// reveal block's height and time. Everything but the secret is public, and the
// secret is the keeper's until the reveal; the block's time is the validators'.
func seedFor(poolID int64, t *Shot, secret []byte, h int64) uint64 {
	var b []byte
	b = append(b, pkgPath...)
	b = binary.BigEndian.AppendUint64(b, uint64(poolID))
	b = binary.BigEndian.AppendUint64(b, uint64(t.N))
	b = append(b, t.Bidder.String()...)
	b = binary.BigEndian.AppendUint64(b, uint64(t.CommitH))
	b = append(b, secret...)
	b = binary.BigEndian.AppendUint64(b, uint64(h))
	b = binary.BigEndian.AppendUint64(b, uint64(time.Now().UnixNano()))
	sum := sha256.Sum256(b)
	return binary.BigEndian.Uint64(sum[:8])
}

// shotHits is the draw: a uniform number in [0, 10000) under the chance.
func shotHits(seed uint64, bps int64) bool {
	return int64(seed%10000) < bps
}

// payDividends credits div to the pool's earlier bidders, pro-rata to what
// each has paid in, skipping the bidder; whatever cannot be placed (no earlier
// bidders, rounding) is returned to go into the pot.
func (p *Pool) payDividends(cur realm, bidder address, div int64) int64 {
	var total int64
	for _, m := range p.Roster {
		if m.Addr != bidder {
			total += m.Paid
		}
	}
	if total == 0 || div == 0 {
		return div
	}
	var paid int64
	for _, m := range p.Roster {
		if m.Addr == bidder {
			continue
		}
		amt := mulDiv(div, m.Paid, total)
		if amt > 0 {
			credit(m.Addr, amt)
			m.Earned += amt
			player(m.Addr).DivEarned += amt
			paid += amt
		}
	}
	p.DivPaid += paid
	return div - paid
}

// member finds or adds a bidder on the roster; a full roster drops its oldest.
// A new member's flag is the one given; once set it is locked for this pool.
func (p *Pool) member(a address, flag string) *Member {
	for _, m := range p.Roster {
		if m.Addr == a {
			return m
		}
	}
	if len(p.Roster) >= RosterMax {
		p.Roster = p.Roster[1:]
	}
	m := &Member{Addr: a, Flag: flag}
	p.Roster = append(p.Roster, m)
	return m
}

// Claim settles a finished pool: everything is credited, and Withdraw sends
// it. TeamShare of the pot goes to the OTHER roster members flying the
// winner's flag, pro-rata by paid-in — or, when nobody else flew it, to all
// the other roster members. Of the rest, the live part (LiveBps) is the
// winner's and the shared part is split among the whole roster pro-rata by
// paid-in. A pool with a single bidder credits them everything. Rounding goes
// to the winner. Anyone may call it.
func Claim(cur realm, id int64) {
	p := pool(id)
	if p.Cancelled {
		panic("pool was cancelled")
	}
	p.settleShots()
	if !p.Over() {
		panic("clock still running")
	}
	if p.Paid {
		panic("already paid out")
	}
	p.Paid = true
	winner := p.LastBidder
	flag := ""
	if m := p.find(winner); m != nil {
		flag = m.Flag
	}
	p.WinnerFlag = flag
	toWinner, _ := p.payout(winner, p.Pot, true)
	if toWinner > 0 {
		credit(winner, toWinner)
		player(winner).Won += toWinner
	}
	p.WinnerPaid = toWinner
	if flag != "" {
		teamWon[flag] += p.Pot
	}
	chain.Emit("Paid", "id", itoa(id), "winner", winner.String(), "pot", itoa(p.Pot), "winnerPaid", itoa(toWinner), "team", itoa(p.TeamPaid), "shared", itoa(p.SharedPaid), "liveBps", itoa(p.LiveBps()))
}

// payout is the close's arithmetic for a winner and a pot: TeamShare to the
// other roster members under the winner's flag (or, when nobody else flew it,
// to all the others), then the shared part of the rest — what the live share
// has slid away from — to the whole roster pro-rata by paid-in; the winner
// keeps the rest and the rounding. With pay it credits and books the shares;
// dry, it only says what the winner would get and what the team would (Take
// prices shots with both).
func (p *Pool) payout(winner address, pot int64, pay bool) (toWinner, teamCut int64) {
	flag := ""
	if m := p.find(winner); m != nil {
		flag = m.Flag
	}
	var team int64
	for _, m := range p.Roster {
		if m.Addr != winner && m.Flag == flag && flag != "" {
			team += m.Paid
		}
	}
	teamFlag := flag
	if team == 0 {
		teamFlag = "" // nobody else flew it: every other bidder is the team
		for _, m := range p.Roster {
			if m.Addr != winner {
				team += m.Paid
			}
		}
	}
	toWinner = pot
	if team == 0 {
		return toWinner, 0 // alone on the roster: everything
	}
	cut := pot * TeamShare / 100
	for _, m := range p.Roster {
		if m.Addr == winner || (teamFlag != "" && m.Flag != teamFlag) {
			continue
		}
		amt := mulDiv(cut, m.Paid, team)
		if amt > 0 {
			toWinner -= amt
			teamCut += amt
			if pay {
				credit(m.Addr, amt)
				player(m.Addr).Won += amt
				p.TeamPaid += amt
			}
		}
	}
	// the rest slides: the live part stays the winner's, the shared part is everyone's by paid-in
	rest := pot - cut
	shared := rest - mulDiv(rest, p.LiveBps(), 10000)
	if shared > 0 {
		var total int64
		for _, m := range p.Roster {
			total += m.Paid
		}
		for _, m := range p.Roster {
			amt := mulDiv(shared, m.Paid, total)
			if amt > 0 && m.Addr != winner {
				toWinner -= amt
				if pay {
					credit(m.Addr, amt)
					player(m.Addr).Won += amt
					p.SharedPaid += amt
				}
			}
		}
	}
	return toWinner, teamCut
}

// Cancel lets the creator take the seed back from a pool nobody has bid on.
func Cancel(cur realm, id int64) {
	caller := userCaller(cur)
	p := pool(id)
	if p.Creator != caller {
		panic("only the creator can cancel")
	}
	if p.Bids > 0 {
		panic("pool already has bids")
	}
	if p.Cancelled {
		panic("already cancelled")
	}
	p.Cancelled = true
	p.Paid = true
	if p.Pot > 0 {
		send(cur, caller, p.Pot)
	}
	chain.Emit("Cancelled", "id", itoa(id))
}

func (p *Pool) find(a address) *Member {
	for _, m := range p.Roster {
		if m.Addr == a {
			return m
		}
	}
	return nil
}

func player(a address) *Player {
	pl := players[a]
	if pl == nil {
		pl = &Player{}
		players[a] = pl
	}
	return pl
}

func send(cur realm, to address, ugnot int64) {
	banker.NewBanker(banker.BankerTypeRealmSend, cur).SendCoins(realmAddr, to, chain.Coins{{"ugnot", ugnot}})
}

// credit books ugnot to an address; Withdraw pays it out.
func credit(to address, ugnot int64) {
	player(to).Owed += ugnot
}

// Withdraw sends the caller everything credited to them: dividends, team
// shares, close splits, slices and won pots.
func Withdraw(cur realm) int64 {
	who := userCaller(cur)
	pl := player(who)
	amt := pl.Owed
	if amt <= 0 {
		panic("nothing to withdraw")
	}
	pl.Owed = 0
	pl.Withdrawn += amt
	send(cur, who, amt)
	chain.Emit("Withdrawn", "to", who.String(), "ugnot", itoa(amt))
	return amt
}

// Owed is what an address could withdraw right now.
func Owed(a address) int64 { return player(a).Owed }

func pool(id int64) *Pool {
	if id < 1 || id > int64(len(pools)) {
		panic("no such pool")
	}
	return pools[id-1]
}

// userCaller is the signer of the transaction, refusing calls relayed through
// another realm so nobody can bid on someone else's behalf, and so no realm can
// pay for a shot and revert on a miss.
func userCaller(cur realm) address {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("must be a direct user call")
	}
	return prev.Address()
}

func ugnotSent() int64 {
	sent := unsafe.OriginSend()
	for _, c := range sent {
		if c.Denom != "ugnot" {
			panic("only ugnot is accepted")
		}
	}
	return sent.AmountOf("ugnot")
}

func cleanName(s string) string {
	s = strings.TrimSpace(s)
	if s == "" || len(s) > MaxNameLen {
		panic("name must be 1-40 characters")
	}
	for _, c := range s {
		if c < 0x20 || c == 0x7f {
			panic("name has control characters")
		}
	}
	return s
}

// cleanFlag accepts a two-letter country code, upper-cased; anything else is "".
func cleanFlag(s string) string {
	s = strings.ToUpper(strings.TrimSpace(s))
	if len(s) != 2 || s[0] < 'A' || s[0] > 'Z' || s[1] < 'A' || s[1] > 'Z' {
		return ""
	}
	return s
}

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

func parseID(s string) int64 {
	n, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		panic("bad pool id")
	}
	return n
}

func parseNum(s string) int64 {
	n, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		panic("bad number")
	}
	return n
}

// GNOT formats ugnot as GNOT with the trailing zeros trimmed.
func GNOT(ugnot int64) string {
	whole, frac := ugnot/1_000_000, ugnot%1_000_000
	if frac == 0 {
		return itoa(whole) + " GNOT"
	}
	f := strconv.FormatInt(1_000_000+frac, 10)[1:]
	return itoa(whole) + "." + strings.TrimRight(f, "0") + " GNOT"
}

func short(a address) string {
	s := a.String()
	if len(s) < 12 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

func dur(sec int64) string {
	if sec <= 0 {
		return "0s"
	}
	d, h, m, s := sec/86400, sec%86400/3600, sec%3600/60, sec%60
	out := ""
	if d > 0 {
		out += itoa(d) + "d "
	}
	if d > 0 || h > 0 {
		out += itoa(h) + "h "
	}
	if d > 0 || h > 0 || m > 0 {
		out += itoa(m) + "m "
	}
	return out + itoa(s) + "s"
}

// --- rendering ---------------------------------------------------------------

// Render serves gnoweb ("" and "<id>") and the page ("json", "json/<id>",
// "me/<address>", "teams").
func Render(path string) string {
	path = strings.Trim(path, "/")
	switch {
	case path == "json":
		return jsonAll()
	case strings.HasPrefix(path, "json/"):
		return pool(parseID(path[5:])).json(true)
	case strings.HasPrefix(path, "me/"):
		return jsonMe(address(path[3:]))
	case path == "teams":
		return jsonTeams()
	case path == "commits":
		return jsonCommits()
	case path == "":
		return markdownAll()
	default:
		return pool(parseID(path)).markdown()
	}
}

func unix(t time.Time) string {
	if t.IsZero() {
		return "0"
	}
	return itoa(t.Unix())
}

func jbool(b bool) string {
	if b {
		return "true"
	}
	return "false"
}

func (p *Pool) json(detail bool) string {
	var b strings.Builder
	b.WriteString("{\"id\":" + itoa(p.ID))
	b.WriteString(",\"name\":" + strconv.Quote(p.Name))
	b.WriteString(",\"creator\":\"" + p.Creator.String() + "\"")
	b.WriteString(",\"window\":" + itoa(p.Window))
	b.WriteString(",\"life\":" + itoa(p.Life))
	b.WriteString(",\"basePrice\":" + itoa(p.BasePrice))
	b.WriteString(",\"seed\":" + itoa(p.Seed))
	b.WriteString(",\"pot\":" + itoa(p.Pot))
	b.WriteString(",\"bids\":" + itoa(p.Bids))
	b.WriteString(",\"nextPrice\":" + itoa(p.NextPrice()))
	b.WriteString(",\"lastBidder\":\"" + p.LastBidder.String() + "\"")
	b.WriteString(",\"lastBidAt\":" + unix(p.LastBidAt))
	b.WriteString(",\"firstBidAt\":" + unix(p.FirstBidAt))
	b.WriteString(",\"deadline\":" + unix(p.Deadline()))
	b.WriteString(",\"lastDay\":" + unix(p.LastDay()))
	b.WriteString(",\"liveBps\":" + itoa(p.LiveBps()))
	b.WriteString(",\"clock\":" + itoa(p.Clock))
	b.WriteString(",\"createdAt\":" + unix(p.CreatedAt))
	b.WriteString(",\"over\":" + jbool(p.Over()))
	b.WriteString(",\"popped\":" + jbool(p.Popped))
	b.WriteString(",\"paid\":" + jbool(p.Paid))
	b.WriteString(",\"cancelled\":" + jbool(p.Cancelled))
	b.WriteString(",\"bidders\":" + itoa(int64(len(p.Roster))))
	b.WriteString(",\"divPaid\":" + itoa(p.DivPaid))
	b.WriteString(",\"refPaid\":" + itoa(p.RefPaid))
	b.WriteString(",\"creatorPaid\":" + itoa(p.CreatorPaid))
	b.WriteString(",\"treasuryPaid\":" + itoa(p.TreasuryPaid))
	b.WriteString(",\"shotPaid\":" + itoa(p.ShotPaid))
	b.WriteString(",\"teamPaid\":" + itoa(p.TeamPaid))
	b.WriteString(",\"sharedPaid\":" + itoa(p.SharedPaid))
	b.WriteString(",\"winnerPaid\":" + itoa(p.WinnerPaid))
	pending := int64(0)
	for _, t := range p.Shots {
		if !t.Resolved {
			pending++
		}
	}
	b.WriteString(",\"shots\":" + itoa(int64(len(p.Shots))) + ",\"misses\":" + itoa(p.Misses) + ",\"voided\":" + itoa(p.Voided) + ",\"late\":" + itoa(p.Late) + ",\"pending\":" + itoa(pending) + ",\"escrow\":" + itoa(p.ShotEscrow))
	flag := p.WinnerFlag
	if m := p.find(p.LastBidder); m != nil && flag == "" {
		flag = m.Flag
	}
	b.WriteString(",\"flag\":\"" + flag + "\"")
	// what each flag has paid into this pool
	b.WriteString(",\"teams\":{")
	seen := map[string]int64{}
	order := []string{}
	for _, m := range p.Roster {
		if m.Flag == "" {
			continue
		}
		if _, ok := seen[m.Flag]; !ok {
			order = append(order, m.Flag)
		}
		seen[m.Flag] += m.Paid
	}
	for i, f := range order {
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString("\"" + f + "\":" + itoa(seen[f]))
	}
	b.WriteString("}")
	if detail {
		b.WriteString(",\"history\":[")
		for i := len(p.History) - 1; i >= 0; i-- { // newest first
			h := p.History[i]
			if i < len(p.History)-1 {
				b.WriteString(",")
			}
			b.WriteString("{\"n\":" + itoa(h.N) + ",\"bidder\":\"" + h.Bidder.String() + "\",\"flag\":\"" + h.Flag + "\",\"price\":" + itoa(h.Price) + ",\"shot\":" + itoa(h.Shot) + ",\"clock\":" + itoa(h.Clock) + ",\"pot\":" + itoa(h.Pot) + ",\"at\":" + unix(h.At) + "}")
		}
		b.WriteString("],\"roster\":[")
		for i, m := range p.Roster {
			if i > 0 {
				b.WriteString(",")
			}
			b.WriteString("{\"addr\":\"" + m.Addr.String() + "\",\"flag\":\"" + m.Flag + "\",\"paid\":" + itoa(m.Paid) + ",\"earned\":" + itoa(m.Earned) + "}")
		}
		b.WriteString("],\"shotlog\":[")
		for i := len(p.Shots) - 1; i >= 0; i-- { // newest first
			t := p.Shots[i]
			if i < len(p.Shots)-1 {
				b.WriteString(",")
			}
			b.WriteString("{\"n\":" + itoa(t.N) + ",\"bidder\":\"" + t.Bidder.String() + "\",\"paid\":" + itoa(t.Paid) + ",\"take\":" + itoa(t.Take) + ",\"bps\":" + itoa(t.Bps) + ",\"commitH\":" + itoa(t.CommitH) + ",\"commit\":\"" + hex.EncodeToString([]byte(t.Hash)) + "\",\"revealAt\":" + itoa(t.CommitH+ShotDelay) + ",\"revealBy\":" + itoa(t.CommitH+ShotDelay+ShotWindow) + ",\"resolved\":" + jbool(t.Resolved) + ",\"hit\":" + jbool(t.Won) + ",\"void\":" + jbool(t.Void) + ",\"drawH\":" + itoa(t.DrawH) + "}")
		}
		b.WriteString("]")
	}
	b.WriteString("}")
	return b.String()
}

// jsonCommits lists the unused commitments in order, hex, so a keeper that
// starts can tell which of them it holds the secrets for and Retire the rest.
func jsonCommits() string {
	var b strings.Builder
	b.WriteString("{\"height\":" + itoa(runtime.ChainHeight()) + ",\"commits\":[")
	for i := head; i < len(commits); i++ {
		if i > head {
			b.WriteString(",")
		}
		b.WriteString("\"" + hex.EncodeToString([]byte(commits[i])) + "\"")
	}
	b.WriteString("]}")
	return b.String()
}

// commitHead is the next commitment a shot would take, hex, "" when none is free.
func commitHead() string {
	if head >= len(commits) {
		return ""
	}
	return hex.EncodeToString([]byte(commits[head]))
}

func jsonAll() string {
	var b strings.Builder
	b.WriteString("{\"now\":" + itoa(time.Now().Unix()) + ",\"height\":" + itoa(runtime.ChainHeight()) + ",\"realm\":\"" + pkgPath + "\"")
	b.WriteString(",\"split\":{\"pot\":" + itoa(PotShare) + ",\"div\":" + itoa(DivShare) + ",\"ref\":" + itoa(RefShare) + ",\"creator\":" + itoa(CreatorShare) + ",\"treasury\":" + itoa(TreasuryShare) + ",\"team\":" + itoa(TeamShare) + ",\"roster\":" + itoa(int64(RosterMax)) +
		",\"shotMaxBps\":" + itoa(ShotMaxBps) + ",\"shotFair\":" + itoa(ShotFair) + ",\"shotDelay\":" + itoa(ShotDelay) + ",\"shotWindow\":" + itoa(ShotWindow) + ",\"minClock\":" + itoa(MinClock) +
		",\"minShot\":" + itoa(MinShot) + ",\"revealTip\":" + itoa(RevealTip) + ",\"keeperFresh\":" + itoa(KeeperFresh) + ",\"liveFloor\":" + itoa(LiveFloor) + "}")
	b.WriteString(",\"shotsOn\":" + jbool(shotsOn))
	b.WriteString(",\"treasury\":\"" + treasuryAddr.String() + "\",\"treasuryPaid\":" + itoa(treasuryPaid))
	b.WriteString(",\"keeper\":\"" + keeper.String() + "\",\"keeperSeen\":" + unix(keeperSeen) + ",\"commitsFree\":" + itoa(int64(len(commits)-head)) + ",\"commitHead\":\"" + commitHead() + "\",\"voided\":" + itoa(voided) + ",\"late\":" + itoa(late))
	b.WriteString(",\"pools\":[")
	for i, p := range pools {
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString(p.json(false))
	}
	b.WriteString("],\"teams\":" + jsonTeams() + "}")
	return b.String()
}

// jsonTeams is the country leaderboard: paid in, won, and players per flag.
func jsonTeams() string {
	var b strings.Builder
	b.WriteString("{")
	i := 0
	for f, paid := range teamPaid {
		if i > 0 {
			b.WriteString(",")
		}
		i++
		b.WriteString("\"" + f + "\":{\"paid\":" + itoa(paid) + ",\"won\":" + itoa(teamWon[f]) + ",\"players\":" + itoa(teamSize[f]) + "}")
	}
	b.WriteString("}")
	return b.String()
}

// jsonMe is what the page shows a connected wallet about itself.
func jsonMe(a address) string {
	pl := players[a]
	if pl == nil {
		pl = &Player{}
	}
	return "{\"addr\":\"" + a.String() + "\",\"referrer\":\"" + pl.Referrer.String() + "\",\"recruits\":" + itoa(pl.Recruits) +
		",\"flag\":\"" + pl.Flag + "\",\"bids\":" + itoa(pl.Bids) + ",\"paid\":" + itoa(pl.Paid) +
		",\"divEarned\":" + itoa(pl.DivEarned) + ",\"refEarned\":" + itoa(pl.RefEarned) + ",\"won\":" + itoa(pl.Won) +
		",\"shots\":" + itoa(pl.Shots) + ",\"hits\":" + itoa(pl.Hits) + ",\"owed\":" + itoa(pl.Owed) + ",\"withdrawn\":" + itoa(pl.Withdrawn) + "}"
}

func (p *Pool) status() string {
	switch {
	case p.Cancelled:
		return "cancelled"
	case p.Over():
		s := "won by " + short(p.LastBidder)
		if p.Popped {
			s = "popped by " + short(p.LastBidder)
		}
		if !p.Paid {
			s += " (unclaimed)"
		}
		return s
	case p.Bids == 0:
		return "no bids yet · " + dur(p.Window) + " window · next " + GNOT(p.NextPrice())
	default:
		left := p.Deadline().Unix() - time.Now().Unix()
		s := dur(left) + " left"
		if p.Clock < p.Window {
			s += " (⚡ " + dur(p.Clock) + " clock)"
		}
		return s + " · " + short(p.LastBidder) + " on top · next " + GNOT(p.NextPrice()) + " · winner's share " + itoa(p.LiveBps()/100) + "%"
	}
}

func markdownAll() string {
	var b strings.Builder
	b.WriteString("# Bubble Rumble v5\n\n")
	b.WriteString("Last bid standing takes the pot. Of every bid, 50% goes into the pot, 30% is paid at once to the pool's earlier bidders, 10% to whoever invited the bidder, 5% to the pool's creator and 5% to the BUBBLE treasury (spent only by a vote of the BUBBLE holders). ")
	b.WriteString("Earnings are credited and withdrawn with Withdraw. At the close " + itoa(TeamShare) + "% of the pot goes to the other bidders who flew the winner's flag. Every pool has a last day: as it nears, the winner's own share slides toward a split of the pot among all its bidders. A bid may carry a shot at the bubble: a chance of at most " + itoa(ShotMaxBps/100) + "% to pop it and take the pot, drawn by the keeper's commit-reveal a few blocks later (the keeper never bids; a shot it fails to reveal in time is a miss); every miss is counted on the bubble.\n\n")
	b.WriteString("Play at [bubblerumble.net](https://bubblerumble.net).\n\n## Pools\n\n")
	if len(pools) == 0 {
		b.WriteString("_none yet_\n")
	}
	for _, p := range pools {
		b.WriteString("- [#" + itoa(p.ID) + " " + p.Name + "](/r/g1leu8d2vsplhehcfkjg50mwgdpxdkt8tztu95wr/bubblerumble5:" + itoa(p.ID) + ") · " + GNOT(p.Pot) + " · " + p.status() + "\n")
	}
	return b.String()
}

func (p *Pool) markdown() string {
	var b strings.Builder
	b.WriteString("# " + p.Name + "\n\n")
	b.WriteString("- pot: **" + GNOT(p.Pot) + "**\n- status: " + p.status() + "\n- window: " + dur(p.Window) + " · life: " + dur(p.Life) + "\n- base price: " + GNOT(p.BasePrice) + " · next bid: " + GNOT(p.NextPrice()) + "\n- bids: " + itoa(p.Bids) + " · creator: " + short(p.Creator) + "\n")
	if !p.LastDay().IsZero() {
		b.WriteString("- last day: " + p.LastDay().UTC().Format("2006-01-02 15:04 UTC") + " · winner's share now " + itoa(p.LiveBps()/100) + "%\n")
	}
	if len(p.Shots) > 0 {
		b.WriteString("- shots: " + itoa(int64(len(p.Shots))) + " · misses: " + itoa(p.Misses) + " · unrevealed: " + itoa(p.Voided) + "\n")
	}
	b.WriteString("\n## Bids\n\n")
	if len(p.History) == 0 {
		b.WriteString("_none yet_\n")
	}
	for i := len(p.History) - 1; i >= 0; i-- {
		h := p.History[i]
		line := "- #" + itoa(h.N) + " " + short(h.Bidder)
		if h.Flag != "" {
			line += " (" + h.Flag + ")"
		}
		line += " paid " + GNOT(h.Price)
		if h.Shot > 0 {
			line += " + a " + GNOT(h.Shot) + " shot"
		}
		b.WriteString(line + " · pot " + GNOT(h.Pot) + "\n")
	}
	return b.String()
}

package avl

type Node struct {
	key       string // key is the unique identifier for the node.
	value     any    // value is the data stored in the node.
	height    int8   // height is the height of the node in the tree.
	size      int    // size is the number of leaf nodes (key-value pairs) in the subtree rooted at this node.
	leftNode  *Node  // leftNode is the left child of the node.
	rightNode *Node  // rightNode is the right child of the node.
}

func NewNode(key string, value any) *Node {
	return &Node{
		key:    key,
		value:  value,
		height: 0,
		size:   1,
	}
}

func (node *Node) Size() int {
	if node == nil {
		return 0
	}
	return node.size
}

func (node *Node) IsLeaf() bool {
	return node.height == 0
}

func (node *Node) Key() string {
	return node.key
}

func (node *Node) Value() any {
	return node.value
}

func (node *Node) _copy() *Node {
	if node.height == 0 {
		panic("Why are you copying a value node?")
	}
	return &Node{
		key:       node.key,
		height:    node.height,
		size:      node.size,
		leftNode:  node.leftNode,
		rightNode: node.rightNode,
	}
}

func (node *Node) Has(key string) (has bool) {
	if node == nil {
		return false
	}
	if node.key == key {
		return true
	}
	if node.height == 0 {
		return false
	} else {
		if key < node.key {
			return node.getLeftNode().Has(key)
		} else {
			return node.getRightNode().Has(key)
		}
	}
}

func (node *Node) Get(key string) (index int, value any, exists bool) {
	if node == nil {
		return 0, nil, false
	}

	if node.height == 0 {
		if node.key == key {
			return 0, node.value, true
		} else if node.key < key {
			return 1, nil, false
		} else {
			return 0, nil, false
		}
	} else {
		if key < node.key {
			return node.getLeftNode().Get(key)
		} else {
			rightNode := node.getRightNode()
			index, value, exists = rightNode.Get(key)
			index += node.size - rightNode.size
			return index, value, exists
		}
	}
}

func (node *Node) GetByIndex(index int) (key string, value any) {
	if index < 0 {
		panic("GetByIndex: negative index not allowed")
	}

	if node.height == 0 {
		if index != 0 {
			panic("GetByIndex asked for invalid index")
		}
		return node.key, node.value
	} else {
		leftNode := node.getLeftNode()
		if index < leftNode.size {
			return leftNode.GetByIndex(index)
		} else {
			return node.getRightNode().GetByIndex(index - leftNode.size)
		}
	}
}

func (node *Node) Set(key string, value any) (newSelf *Node, updated bool) {
	if node == nil {
		return NewNode(key, value), false
	}
	if node.height == 0 {
		if key < node.key {
			return &Node{
				key:       node.key,
				height:    1,
				size:      2,
				leftNode:  NewNode(key, value),
				rightNode: node,
			}, false
		} else if key == node.key {
			return NewNode(key, value), true
		} else {
			return &Node{
				key:       key,
				height:    1,
				size:      2,
				leftNode:  node,
				rightNode: NewNode(key, value),
			}, false
		}
	} else {
		node = node._copy()
		if key < node.key {
			node.leftNode, updated = node.getLeftNode().Set(key, value)
		} else {
			node.rightNode, updated = node.getRightNode().Set(key, value)
		}
		if updated {
			return node, updated
		} else {
			node.calcHeightAndSize()
			return node.balance(), updated
		}
	}
}

func (node *Node) Remove(key string) (
	newNode *Node, newKey string, value any, removed bool,
) {
	if node == nil {
		return nil, "", nil, false
	}
	if node.height == 0 {
		if key == node.key {
			return nil, "", node.value, true
		} else {
			return node, "", nil, false
		}
	} else {
		if key < node.key {
			var newLeftNode *Node
			newLeftNode, newKey, value, removed = node.getLeftNode().Remove(key)
			if !removed {
				return node, "", value, false
			} else if newLeftNode == nil { // left node held value, was removed
				return node.rightNode, node.key, value, true
			}
			node = node._copy()
			node.leftNode = newLeftNode
			node.calcHeightAndSize()
			node = node.balance()
			return node, newKey, value, true
		} else {
			var newRightNode *Node
			newRightNode, newKey, value, removed = node.getRightNode().Remove(key)
			if !removed {
				return node, "", value, false
			} else if newRightNode == nil { // right node held value, was removed
				return node.leftNode, "", value, true
			}
			node = node._copy()
			node.rightNode = newRightNode
			if newKey != "" {
				node.key = newKey
			}
			node.calcHeightAndSize()
			node = node.balance()
			return node, "", value, true
		}
	}
}

func (node *Node) getLeftNode() *Node {
	return node.leftNode
}

func (node *Node) getRightNode() *Node {
	return node.rightNode
}

func (node *Node) rotateRight() *Node {
	node = node._copy()
	l := node.getLeftNode()
	_l := l._copy()

	_lrCached := _l.rightNode
	_l.rightNode = node
	node.leftNode = _lrCached

	node.calcHeightAndSize()
	_l.calcHeightAndSize()

	return _l
}

func (node *Node) rotateLeft() *Node {
	node = node._copy()
	r := node.getRightNode()
	_r := r._copy()

	_rlCached := _r.leftNode
	_r.leftNode = node
	node.rightNode = _rlCached

	node.calcHeightAndSize()
	_r.calcHeightAndSize()

	return _r
}

func (node *Node) calcHeightAndSize() {
	node.height = maxInt8(node.getLeftNode().height, node.getRightNode().height) + 1
	node.size = node.getLeftNode().size + node.getRightNode().size
}

func (node *Node) calcBalance() int {
	return int(node.getLeftNode().height) - int(node.getRightNode().height)
}

func (node *Node) balance() (newSelf *Node) {
	balance := node.calcBalance()
	if balance > 1 {
		if node.getLeftNode().calcBalance() >= 0 {
			return node.rotateRight()
		} else {
			left := node.getLeftNode()
			node.leftNode = left.rotateLeft()
			return node.rotateRight()
		}
	}
	if balance < -1 {
		if node.getRightNode().calcBalance() <= 0 {
			return node.rotateLeft()
		} else {
			right := node.getRightNode()
			node.rightNode = right.rotateRight()
			return node.rotateLeft()
		}
	}
	return node
}

func (node *Node) Iterate(start, end string, cb func(*Node) bool) bool {
	return node.TraverseInRange(start, end, true, true, cb)
}

func (node *Node) ReverseIterate(start, end string, cb func(*Node) bool) bool {
	return node.TraverseInRange(start, end, false, true, cb)
}

func (node *Node) TraverseInRange(start, end string, ascending bool, leavesOnly bool, cb func(*Node) bool) bool {
	if node == nil {
		return false
	}
	afterStart := (start == "" || start < node.key)
	startOrAfter := (start == "" || start <= node.key)
	beforeEnd := false
	if ascending {
		beforeEnd = (end == "" || node.key < end)
	} else {
		beforeEnd = (end == "" || node.key <= end)
	}

	stop := false
	if (!node.IsLeaf() && !leavesOnly) ||
		(node.IsLeaf() && startOrAfter && beforeEnd) {
		stop = cb(node)
		if stop {
			return stop
		}
	}
	if node.IsLeaf() {
		return stop
	}

	if ascending {
		if afterStart {
			stop = node.getLeftNode().TraverseInRange(start, end, ascending, leavesOnly, cb)
		}
		if stop {
			return stop
		}
		if beforeEnd {
			stop = node.getRightNode().TraverseInRange(start, end, ascending, leavesOnly, cb)
		}
	} else {
		if beforeEnd {
			stop = node.getRightNode().TraverseInRange(start, end, ascending, leavesOnly, cb)
		}
		if stop {
			return stop
		}
		if afterStart {
			stop = node.getLeftNode().TraverseInRange(start, end, ascending, leavesOnly, cb)
		}
	}

	return stop
}

func (node *Node) TraverseByOffset(offset, limit int, ascending bool, leavesOnly bool, cb func(*Node) bool) bool {
	if node == nil {
		return false
	}

	if offset < 0 {
		offset = 0
	}

	if limit <= 0 || offset >= node.size {
		return false
	}
	if node.IsLeaf() {
		if offset > 0 {
			return false
		}
		return cb(node)
	}

	return node.traverseByOffset(offset, limit, ascending, leavesOnly, cb)
}

func (node *Node) traverseByOffset(offset, limit int, ascending bool, leavesOnly bool, cb func(*Node) bool) bool {
	if !leavesOnly {
		if cb(node) {
			return true // Stop traversal if callback returns true
		}
	}
	first, second := node.getLeftNode(), node.getRightNode()
	if !ascending {
		first, second = second, first
	}
	if first.IsLeaf() {
		if offset > 0 {
			offset--
		} else {
			if cb(first) {
				return true // Stop traversal if callback returns true
			}
			limit--
			if limit <= 0 {
				return true // Stop traversal when limit is reached
			}
		}
	} else {
		if offset >= first.size {
			offset -= first.size // 1
		} else {
			if first.traverseByOffset(offset, limit, ascending, leavesOnly, cb) {
				return true
			}
			delta := first.size - offset
			offset = 0
			if delta >= limit {
				return true // 3
			}
			limit -= delta // 2
		}
	}

	if second.IsLeaf() {
		return cb(second)
	}
	return second.traverseByOffset(offset, limit, ascending, leavesOnly, cb)
}

func (node *Node) lmd() *Node {
	if node.height == 0 {
		return node
	}
	return node.getLeftNode().lmd()
}

func (node *Node) rmd() *Node {
	if node.height == 0 {
		return node
	}
	return node.getRightNode().rmd()
}

func maxInt8(a, b int8) int8 {
	if a > b {
		return a
	}
	return b
}

package avl

type ITree interface {

	Size() int
	Has(key string) bool
	Get(key string) any
	GetByIndex(index int) (key string, value any)
	Iterate(start, end string, cb IterCbFn) bool
	ReverseIterate(start, end string, cb IterCbFn) bool
	IterateByOffset(offset int, count int, cb IterCbFn) bool
	ReverseIterateByOffset(offset int, count int, cb IterCbFn) bool

	Set(key string, value any) (updated bool)
	Remove(key string) (value any, removed bool)
}

type IterCbFn func(key string, value any) bool

type Tree struct {
	node *Node
}

func NewTree() *Tree {
	return &Tree{
		node: nil,
	}
}

func (tree *Tree) Size() int {
	return tree.node.Size()
}

func (tree *Tree) Has(key string) (has bool) {
	return tree.node.Has(key)
}

func (tree *Tree) Get(key string) any {
	_, value, _ := tree.node.Get(key)
	return value
}

func (tree *Tree) GetByIndex(index int) (key string, value any) {
	return tree.node.GetByIndex(index)
}

func (tree *Tree) Set(key string, value any) (updated bool) {
	newnode, updated := tree.node.Set(key, value)
	tree.node = newnode
	return updated
}

func (tree *Tree) Remove(key string) (value any, removed bool) {
	newnode, _, value, removed := tree.node.Remove(key)
	tree.node = newnode
	return value, removed
}

func (tree *Tree) Iterate(start, end string, cb IterCbFn) bool {
	return tree.node.TraverseInRange(start, end, true, true,
		func(node *Node) bool {
			return cb(node.Key(), node.Value())
		},
	)
}

func (tree *Tree) ReverseIterate(start, end string, cb IterCbFn) bool {
	return tree.node.TraverseInRange(start, end, false, true,
		func(node *Node) bool {
			return cb(node.Key(), node.Value())
		},
	)
}

func (tree *Tree) IterateByOffset(offset int, count int, cb IterCbFn) bool {
	return tree.node.TraverseByOffset(offset, count, true, true,
		func(node *Node) bool {
			return cb(node.Key(), node.Value())
		},
	)
}

func (tree *Tree) ReverseIterateByOffset(offset int, count int, cb IterCbFn) bool {
	return tree.node.TraverseByOffset(offset, count, false, true,
		func(node *Node) bool {
			return cb(node.Key(), node.Value())
		},
	)
}

var _ ITree = (*Tree)(nil)

package grc721v2

import (
	"chain"
	unsaferealm "chain/runtime/unsafe"
	"math/overflow"
	"strconv"

	"gno.land/p/g1wx60nkcp5lfsxmedeg7sfs47tzxkath05u63t4/avl"
	"gno.land/p/nt/ufmt/v0"
)

type BasicNFT struct {
	name              string
	symbol            string
	origRealm         string   // owning realm's package path
	owners            avl.Tree // tokenId -> OwnerAddress
	balances          avl.Tree // OwnerAddress -> TokenCount
	tokenApprovals    avl.Tree // TokenId -> ApprovedAddress
	tokenURIs         avl.Tree // TokenId -> URIs
	operatorApprovals avl.Tree // "OwnerAddress:OperatorAddress" -> bool
}

func NewBasicNFT(_ int, _ realm, name, symbol string) *BasicNFT {
	pkgPath := unsaferealm.CurrentRealm().PkgPath()
	if pkgPath == "" {
		panic(ErrNotRealm)
	}
	if !validName(name) {
		panic(ErrInvalidName)
	}
	if !validSymbol(symbol) {
		panic(ErrInvalidSymbol)
	}

	return &BasicNFT{
		name:      name,
		symbol:    symbol,
		origRealm: pkgPath,

		owners:            avl.Tree{},
		balances:          avl.Tree{},
		tokenApprovals:    avl.Tree{},
		tokenURIs:         avl.Tree{},
		operatorApprovals: avl.Tree{},
	}
}

func (s *BasicNFT) Name() string      { return s.name }
func (s *BasicNFT) Symbol() string    { return s.symbol }
func (s *BasicNFT) TokenCount() int64 { return int64(s.owners.Size()) }

func (s *BasicNFT) ID() string {
	return s.origRealm + "." + s.symbol
}

func (s *BasicNFT) BalanceOf(addr address) (int64, error) {
	if err := isValidAddress(addr); err != nil {
		return 0, err
	}

	balance := s.balances.Get(addr.String())
	if balance == nil {
		return 0, nil
	}

	return balance.(int64), nil
}

func (s *BasicNFT) OwnerOf(tid TokenID) (address, error) {
	owner := s.owners.Get(string(tid))
	if owner == nil {
		return "", ErrInvalidTokenId
	}

	return owner.(address), nil
}

func (s *BasicNFT) TokenURI(tid TokenID) (string, error) {
	uri := s.tokenURIs.Get(tid.String())
	if uri == nil {
		return "", ErrInvalidTokenId
	}

	return uri.(string), nil
}

func (s *BasicNFT) SetTokenURI(caller address, tid TokenID, tURI TokenURI) (bool, error) {
	if !s.exists(tid) {
		return false, ErrInvalidTokenId
	}

	owner, err := s.OwnerOf(tid)
	if err != nil {
		return false, err
	}
	if caller != owner {
		return false, ErrCallerIsNotOwner
	}
	s.tokenURIs.Set(tid.String(), tURI.String())

	chain.Emit(
		TokenURIUpdateEvent,
		"token", s.ID(),
		"tokenId", tid.String(),
	)

	return true, nil
}

func (s *BasicNFT) IsApprovedForAll(owner, operator address) bool {
	key := owner.String() + ":" + operator.String()
	approved := s.operatorApprovals.Get(key)
	if approved == nil {
		return false
	}

	return approved.(bool)
}

func (s *BasicNFT) Approve(caller, to address, tid TokenID) error {
	if err := isValidAddress(to); err != nil {
		return err
	}

	owner, err := s.OwnerOf(tid)
	if err != nil {
		return err
	}
	if owner == to {
		return ErrApprovalToCurrentOwner
	}

	if caller != owner && !s.IsApprovedForAll(owner, caller) {
		return ErrCallerIsNotOwnerOrApproved
	}

	tidStr := tid.String()
	s.tokenApprovals.Set(tidStr, to)

	chain.Emit(
		ApprovalEvent,
		"token", s.ID(),
		"owner", owner.String(),
		"to", to.String(),
		"tokenId", tidStr,
	)

	return nil
}

func (s *BasicNFT) GetApproved(tid TokenID) (address, error) {
	addr := s.tokenApprovals.Get(tid.String())
	if addr == nil {
		return zeroAddress, ErrTokenIdNotHasApproved
	}

	return addr.(address), nil
}

func (s *BasicNFT) SetApprovalForAll(caller, operator address, approved bool) error {
	if err := isValidAddress(operator); err != nil {
		return ErrInvalidAddress
	}
	return s.setApprovalForAll(caller, operator, approved)
}

func (s *BasicNFT) SafeTransferFrom(caller, from, to address, tid TokenID) error {
	if !s.isApprovedOrOwner(caller, tid) {
		return ErrCallerIsNotOwnerOrApproved
	}

	err := s.transfer(from, to, tid)
	if err != nil {
		return err
	}

	if !s.checkOnGRC721Received(from, to, tid) {
		return ErrTransferToNonGRC721Receiver
	}

	return nil
}

func (s *BasicNFT) TransferFrom(caller, from, to address, tid TokenID) error {
	if !s.isApprovedOrOwner(caller, tid) {
		return ErrCallerIsNotOwnerOrApproved
	}

	err := s.transfer(from, to, tid)
	if err != nil {
		return err
	}

	return nil
}

func (s *BasicNFT) Mint(to address, tid TokenID) error {
	return s.mint(to, tid)
}

func (s *BasicNFT) SafeMint(to address, tid TokenID) error {
	err := s.mint(to, tid)
	if err != nil {
		return err
	}

	if !s.checkOnGRC721Received(zeroAddress, to, tid) {
		return ErrTransferToNonGRC721Receiver
	}

	return nil
}

func (s *BasicNFT) Burn(tid TokenID) error {
	owner, err := s.OwnerOf(tid)
	if err != nil {
		return err
	}

	s.beforeTokenTransfer(owner, zeroAddress, tid, 1)

	tidStr := tid.String()
	s.tokenApprovals.Remove(tidStr)
	balance, err := s.BalanceOf(owner)
	if err != nil {
		return err
	}
	balance = overflow.Sub64p(balance, 1)

	ownerStr := owner.String()
	s.balances.Set(ownerStr, balance)
	s.owners.Remove(tidStr)

	chain.Emit(
		BurnEvent,
		"token", s.ID(),
		"from", ownerStr,
		"tokenId", tidStr,
	)

	s.afterTokenTransfer(owner, zeroAddress, tid, 1)

	return nil
}

func (s *BasicNFT) setApprovalForAll(owner, operator address, approved bool) error {
	if owner == operator {
		return ErrApprovalToCurrentOwner
	}

	key := owner.String() + ":" + operator.String()
	s.operatorApprovals.Set(key, approved)

	chain.Emit(
		ApprovalForAllEvent,
		"token", s.ID(),
		"owner", owner.String(),
		"to", operator.String(),
		"approved", strconv.FormatBool(approved),
	)

	return nil
}

func (s *BasicNFT) transfer(from, to address, tid TokenID) error {
	if err := isValidAddress(from); err != nil {
		return ErrInvalidAddress
	}
	if err := isValidAddress(to); err != nil {
		return ErrInvalidAddress
	}

	if from == to {
		return ErrCannotTransferToSelf
	}

	owner, err := s.OwnerOf(tid)
	if err != nil {
		return err
	}
	if owner != from {
		return ErrTransferFromIncorrectOwner
	}

	s.beforeTokenTransfer(from, to, tid, 1)

	owner, err = s.OwnerOf(tid)
	if err != nil {
		return err
	}
	if owner != from {
		return ErrTransferFromIncorrectOwner
	}

	tidStr := tid.String()
	s.tokenApprovals.Remove(tidStr)
	fromBalance, err := s.BalanceOf(from)
	if err != nil {
		return err
	}
	toBalance, err := s.BalanceOf(to)
	if err != nil {
		return err
	}
	fromBalance = overflow.Sub64p(fromBalance, 1)
	toBalance = overflow.Add64p(toBalance, 1)

	fromStr := from.String()
	toStr := to.String()

	s.balances.Set(fromStr, fromBalance)
	s.balances.Set(toStr, toBalance)
	s.owners.Set(tidStr, to)

	chain.Emit(
		TransferEvent,
		"token", s.ID(),
		"from", fromStr,
		"to", toStr,
		"tokenId", tidStr,
	)

	s.afterTokenTransfer(from, to, tid, 1)

	return nil
}

func (s *BasicNFT) mint(to address, tid TokenID) error {
	if err := isValidAddress(to); err != nil {
		return err
	}

	if s.exists(tid) {
		return ErrTokenIdAlreadyExists
	}

	s.beforeTokenTransfer(zeroAddress, to, tid, 1)

	if s.exists(tid) {
		return ErrTokenIdAlreadyExists
	}

	toBalance, err := s.BalanceOf(to)
	if err != nil {
		return err
	}
	toBalance = overflow.Add64p(toBalance, 1)
	toStr := to.String()
	tidStr := tid.String()
	s.balances.Set(toStr, toBalance)
	s.owners.Set(tidStr, to)

	chain.Emit(
		MintEvent,
		"token", s.ID(),
		"to", toStr,
		"tokenId", tidStr,
	)

	s.afterTokenTransfer(zeroAddress, to, tid, 1)

	return nil
}

func (s *BasicNFT) isApprovedOrOwner(addr address, tid TokenID) bool {
	owner := s.owners.Get(tid.String())
	if owner == nil {
		return false
	}

	ownerAddr := owner.(address)
	if addr == ownerAddr || s.IsApprovedForAll(ownerAddr, addr) {
		return true
	}

	approved, err := s.GetApproved(tid)
	if err != nil {
		return false
	}

	return approved == addr
}

func (s *BasicNFT) exists(tid TokenID) bool {
	return s.owners.Has(tid.String())
}

func (s *BasicNFT) beforeTokenTransfer(from, to address, firstTokenId TokenID, batchSize int64) {
}

func (s *BasicNFT) afterTokenTransfer(from, to address, firstTokenId TokenID, batchSize int64) {
}

func (s *BasicNFT) checkOnGRC721Received(from, to address, tid TokenID) bool {
	return true
}

func (s *BasicNFT) RenderHome() (str string) {
	str += ufmt.Sprintf("# %s ($%s)\n\n", s.name, s.symbol)
	str += ufmt.Sprintf("* **Total supply**: %d\n", s.TokenCount())
